-- biomas
insert into biomes (slug, name, color, subtitle, description, biodiversity_subtitle, stats, fauna, flora, ecosystems) values
('amazonia', 'Amazônia', '#52B788', 'A maior floresta tropical do planeta.', 'Um dos ambientes mais ricos em biodiversidade do mundo, a Amazônia abriga uma enorme variedade de espécies e desempenha um papel fundamental no equilíbrio ambiental.', 'Uma floresta repleta de vida.',
  '[{"value":"49,3%","label":"do território brasileiro"},{"value":"30.000+","label":"espécies de plantas"},{"value":"20%","label":"da água doce do planeta"}]',
  '{"title":"Conheça os habitantes da floresta","description":"A Amazônia abriga uma das maiores diversidades de espécies do planeta. Explore os animais que fazem parte desse ecossistema.","stats":["3.000+ espécies de peixes","950+ espécies de aves"],"categories":["Mamíferos","Aves","Répteis","Anfíbios","Peixes"]}',
  '{"title":"Conheça as plantas da floresta","description":"A Amazônia reúne uma enorme diversidade de plantas, árvores e espécies aquáticas que sustentam a vida na floresta.","stats":["30.000+ espécies de plantas","2.500+ espécies de árvores"],"categories":["Árvores","Palmeiras","Flores","Aquáticas"]}',
  '{"title":"Explore os ambientes da floresta","description":"Descubra os diferentes ambientes que formam a Amazônia e sustentam uma incrível diversidade de vida.","stats":["4 ambientes principais","Terra firme · Rios · Várzeas · Igapós"],"categories":["Terra firme","Rios","Várzeas","Igapós"]}'),

('cerrado', 'Cerrado', '#D4A373', 'A savana mais biodiversa do mundo.', 'Segundo maior bioma do Brasil, o Cerrado abrange o Planalto Central com uma enorme diversidade de espécies adaptadas ao fogo e à seca.', 'Uma savana repleta de vida.',
  '[{"value":"24%","label":"do território brasileiro"},{"value":"12.000+","label":"espécies de plantas"},{"value":"~50%","label":"da área original já desmatada"}]',
  '{"title":"Conheça os habitantes do cerrado","description":"O Cerrado abriga uma rica fauna adaptada ao clima seco e às queimadas naturais.","stats":["837+ espécies de aves","120+ espécies de répteis"],"categories":["Mamíferos","Aves","Répteis","Anfíbios","Insetos"]}',
  '{"title":"Conheça as plantas do cerrado","description":"A vegetação do Cerrado é adaptada ao fogo e à seca, com raízes profundas e cascas grossas.","stats":["12.000+ espécies de plantas","4.400+ endêmicas"],"categories":["Árvores","Arbustos","Gramíneas","Flores"]}',
  '{"title":"Explore os ambientes do cerrado","description":"Do campo limpo às matas de galeria, o Cerrado possui uma diversidade de fitofisionomias.","stats":["11 fitofisionomias","Cerradão · Campo · Veredas · Matas"],"categories":["Cerradão","Campo limpo","Veredas","Matas de galeria"]}'),

('mata-atlantica', 'Mata Atlântica', '#4ECDC4', 'A floresta mais ameaçada do Brasil.', 'Presente ao longo do litoral, a Mata Atlântica já perdeu mais de 70% de sua cobertura original, mas ainda abriga uma das maiores biodiversidades do planeta.', 'Uma floresta repleta de vida.',
  '[{"value":"13%","label":"do território brasileiro"},{"value":"20.000+","label":"espécies de plantas"},{"value":"72%","label":"da população brasileira vive neste bioma"}]',
  '{"title":"Conheça os habitantes da Mata Atlântica","description":"Mesmo reduzida, a Mata Atlântica ainda abriga milhares de espécies, muitas delas endêmicas.","stats":["850+ espécies de aves","370+ espécies de anfíbios"],"categories":["Mamíferos","Aves","Répteis","Anfíbios","Peixes"]}',
  '{"title":"Conheça as plantas da Mata Atlântica","description":"Uma das floras mais diversas do mundo, com altíssimo grau de endemismo.","stats":["20.000+ espécies de plantas","8.000+ endêmicas"],"categories":["Árvores","Bromélias","Orquídeas","Samambaias"]}',
  '{"title":"Explore os ambientes da Mata Atlântica","description":"Da floresta ombrófila aos manguezais, descubra os ambientes desse bioma.","stats":["5 ambientes principais","Floresta · Restinga · Manguezal · Campos"],"categories":["Floresta ombrófila","Restinga","Manguezal","Campos de altitude"]}'),

('caatinga', 'Caatinga', '#E07B54', 'A floresta branca do semiárido.', 'Exclusivamente brasileiro, a Caatinga é o principal bioma do Nordeste. Suas espécies são altamente adaptadas à seca e ao calor intenso.', 'Um semiárido repleto de vida.',
  '[{"value":"11%","label":"do território brasileiro"},{"value":"5.300+","label":"espécies de plantas"},{"value":"318","label":"espécies endêmicas"}]',
  '{"title":"Conheça os habitantes da Caatinga","description":"A fauna da Caatinga é surpreendente, com espécies adaptadas à escassez de água.","stats":["548+ espécies de aves","178+ espécies de répteis"],"categories":["Mamíferos","Aves","Répteis","Anfíbios","Aracnídeos"]}',
  '{"title":"Conheça as plantas da Caatinga","description":"Plantas xerófilas, cactáceas e espécies que armazenam água dominam a paisagem.","stats":["5.300+ espécies de plantas","318 endêmicas"],"categories":["Cactáceas","Árvores","Arbustos","Bromélias"]}',
  '{"title":"Explore os ambientes da Caatinga","description":"Da caatinga arbórea aos campos rupestres, o semiárido tem mais diversidade do que parece.","stats":["4 ambientes principais","Caatinga arbórea · Carrasco · Campos · Brejos"],"categories":["Caatinga arbórea","Carrasco","Campos rupestres","Brejos de altitude"]}'),

('pampa', 'Pampa', '#A7C957', 'Os campos do sul do Brasil.', 'Presente apenas no Rio Grande do Sul, o Pampa é um bioma de campos nativos com uma biodiversidade surpreendente e ameaçada pela expansão agrícola.', 'Campos repletos de vida.',
  '[{"value":"2%","label":"do território brasileiro"},{"value":"3.000+","label":"espécies de plantas"},{"value":"54%","label":"da área original já convertida"}]',
  '{"title":"Conheça os habitantes do Pampa","description":"Os campos abrigam espécies únicas, desde aves migratórias até mamíferos ameaçados.","stats":["480+ espécies de aves","100+ espécies de mamíferos"],"categories":["Mamíferos","Aves","Répteis","Anfíbios","Peixes"]}',
  '{"title":"Conheça as plantas do Pampa","description":"Gramíneas nativas, flores campestres e ervas formam um tapete natural único.","stats":["3.000+ espécies de plantas","450+ espécies de gramíneas"],"categories":["Gramíneas","Flores","Arbustos","Leguminosas"]}',
  '{"title":"Explore os ambientes do Pampa","description":"Dos campos limpos às áreas úmidas, o Pampa tem paisagens variadas.","stats":["3 ambientes principais","Campos · Banhados · Matas ciliares"],"categories":["Campos nativos","Banhados","Matas ciliares"]}'),

('pantanal', 'Pantanal', '#7EB8D0', 'A maior planície alagável do mundo.', 'O Pantanal é um santuário de vida selvagem no coração da América do Sul, com ciclos de cheia e seca que transformam a paisagem ao longo do ano.', 'Águas repletas de vida.',
  '[{"value":"1,8%","label":"do território brasileiro"},{"value":"2.000+","label":"espécies de plantas"},{"value":"650+","label":"espécies de aves"}]',
  '{"title":"Conheça os habitantes do Pantanal","description":"O Pantanal concentra uma das maiores densidades de fauna das Américas.","stats":["650+ espécies de aves","260+ espécies de peixes"],"categories":["Mamíferos","Aves","Répteis","Anfíbios","Peixes"]}',
  '{"title":"Conheça as plantas do Pantanal","description":"A vegetação do Pantanal é uma mistura de espécies de biomas vizinhos, adaptadas às cheias.","stats":["2.000+ espécies de plantas","Vegetação aquática abundante"],"categories":["Árvores","Aquáticas","Gramíneas","Palmeiras"]}',
  '{"title":"Explore os ambientes do Pantanal","description":"Campos inundáveis, corixos e baías formam um mosaico de ambientes.","stats":["4 ambientes principais","Campos · Corixos · Baías · Capões"],"categories":["Campos inundáveis","Corixos","Baías","Capões"]}');

-- espécies — amazônia fauna
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('onca-pintada', 'amazonia', 'fauna', 'Onça-pintada', 'Panthera onca', 'Mamífero', 'Quase ameaçada', '🐆', '/images/fauna/onca-pintada.png', '/images/fauna/onca-pintada-hero.png', '/images/fauna/onca-pintada-detail.png',
  'O maior felino das Américas e predador de topo da cadeia alimentar na Amazônia. É um símbolo da fauna brasileira e essencial para o equilíbrio ecológico.',
  '[{"label":"Peso","value":"até 135 kg"},{"label":"Dieta","value":"Carnívoro"},{"label":"Habitat","value":"Florestas densas"},{"label":"Distribuição","value":"América Central e do Sul"}]',
  '{"title":"Um predador essencial para o equilíbrio da floresta","description":"Como predadora de topo, a onça-pintada ajuda a regular populações de herbívoros e mesopredadores, mantendo o equilíbrio das cadeias alimentares. Sua presença é indicadora de ecossistemas saudáveis e bem preservados."}',
  '[{"title":"Uma mordida poderosa","description":"A onça-pintada possui a mordida mais forte entre todos os felinos em relação ao tamanho do corpo, capaz de perfurar cascos de tartarugas e crânios de jacarés."},{"title":"Manchas únicas","description":"As rosetas da pelagem são únicas em cada indivíduo, funcionando como uma impressão digital que permite identificar cada animal."},{"title":"Boa nadadora","description":"Diferente da maioria dos felinos, a onça-pintada é uma excelente nadadora e frequentemente caça presas na água, como peixes e jacarés."}]'),

('boto-cor-de-rosa', 'amazonia', 'fauna', 'Boto-cor-de-rosa', 'Inia geoffrensis', 'Mamífero', 'Em perigo', '🐬', '/images/fauna/boto-cor-de-rosa.png', null, null,
  'O maior golfinho de rio do mundo, famoso pela coloração rosada dos machos adultos. É cercado de lendas amazônicas e enfrenta ameaças crescentes.',
  '[{"label":"Tamanho","value":"até 2,5 m"},{"label":"Dieta","value":"Peixes"},{"label":"Habitat","value":"Rios e igarapés"},{"label":"Distribuição","value":"Bacia amazônica"}]',
  '{"title":"Guardião da saúde dos rios amazônicos","description":"O boto-cor-de-rosa é um predador de topo nos ecossistemas fluviais, ajudando a controlar as populações de peixes e a manter o equilíbrio das cadeias aquáticas. Sua presença indica rios saudáveis e pouco poluídos."}',
  '[{"title":"Fica mais rosa com a idade","description":"Os machos adultos ficam progressivamente mais rosados ao longo da vida, especialmente durante a excitação ou esforço físico, devido ao aumento do fluxo sanguíneo sob a pele."},{"title":"Pescoço flexível","description":"Diferente de outros golfinhos, o boto possui vértebras cervicais não fundidas, permitindo que gire a cabeça em quase 90 graus para navegar entre troncos submersos."},{"title":"Protagonista de lendas","description":"Segundo o folclore amazônico, o boto se transforma em um jovem elegante durante as festas juninas para seduzir as moças das comunidades ribeirinhas."}]'),

('preguica-real', 'amazonia', 'fauna', 'Preguiça-real', 'Choloepus didactylus', 'Mamífero', 'Pouco preocupante', '🦥', '/images/fauna/preguica.png', null, null,
  'Mamífero arborícola de movimentos extremamente lentos. Passa a maior parte da vida pendurada nas árvores, descendo ao solo apenas uma vez por semana.',
  '[{"label":"Peso","value":"4–8 kg"},{"label":"Dieta","value":"Herbívoro"},{"label":"Habitat","value":"Copa das árvores"},{"label":"Distribuição","value":"América Central e do Sul"}]',
  '{"title":"Um ecossistema vivo nas copas da floresta","description":"A pelagem da preguiça abriga algas, fungos, mariposas e besouros, formando um microecossistema único. Ao descer ao solo para defecar, ela fertiliza as árvores onde vive, contribuindo para o ciclo de nutrientes da floresta."}',
  '[{"title":"Mais rápida na água","description":"Apesar da lentidão em terra, a preguiça é uma boa nadadora e pode se mover até três vezes mais rápido na água do que nas árvores."},{"title":"Pelagem com algas","description":"A coloração esverdeada de sua pelagem é causada por algas que crescem em seus pelos, ajudando na camuflagem entre as folhagens."},{"title":"Digestão ultralenta","description":"A preguiça pode levar até um mês para digerir completamente uma refeição, possuindo um dos metabolismos mais lentos entre os mamíferos."}]'),

('harpia', 'amazonia', 'fauna', 'Harpia', 'Harpia harpyja', 'Ave', 'Quase ameaçada', '🦅', '/images/fauna/harpia.png', null, null,
  'A mais poderosa ave de rapina das Américas, com garras maiores que as de um urso-pardo. Caça macacos e preguiças no dossel da floresta.',
  '[{"label":"Envergadura","value":"até 2 m"},{"label":"Dieta","value":"Carnívoro"},{"label":"Habitat","value":"Dossel florestal"},{"label":"Distribuição","value":"América Central e do Sul"}]',
  '{"title":"A rainha dos céus da floresta","description":"Como predadora de topo no dossel, a harpia controla populações de primatas e preguiças, evitando a superpopulação que poderia degradar a copa da floresta. Necessita de árvores muito altas para nidificar, sendo indicadora de florestas maduras."}',
  '[{"title":"Garras de urso","description":"Suas garras traseiras podem medir até 13 cm — maiores que as de um urso-pardo — e exercem uma pressão de mais de 50 kg por centímetro quadrado."},{"title":"Casal para a vida toda","description":"A harpia forma casais monogâmicos que permanecem juntos por toda a vida, compartilhando o mesmo ninho por décadas."},{"title":"Voo silencioso","description":"Apesar do grande porte, suas penas especializadas permitem voo quase silencioso entre as árvores, surpreendendo as presas no dossel."}]');

-- espécies — amazônia flora
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('castanheira', 'amazonia', 'flora', 'Castanheira', 'Bertholletia excelsa', 'Árvore', 'Vulnerável', '🌳', '/images/flora/castanheira.png', '/images/flora/castanheira-hero.png', '/images/flora/castanheira-detail.png',
  'Uma das maiores árvores da Amazônia, podendo atingir 50 metros. Produz a castanha-do-pará, essencial para a economia extrativista da região.',
  '[{"label":"Altura","value":"até 50 m"},{"label":"Fruto","value":"Castanha-do-pará"},{"label":"Uso","value":"Alimentício"},{"label":"Distribuição","value":"Amazônia"}]',
  '{"title":"Uma árvore essencial para a floresta","description":"A castanheira sustenta uma rede ecológica complexa: depende de abelhas específicas para polinização e de cutias para dispersão de sementes. Sua exploração extrativista gera renda para comunidades tradicionais, incentivando a conservação da floresta em pé."}',
  '[{"title":"Pode viver por muitos anos","description":"A castanheira é uma árvore longeva que pode permanecer na floresta por séculos, com indivíduos estimados em mais de 500 anos de idade."},{"title":"Seus frutos são enormes","description":"O ouriço da castanheira pesa até 2 kg e contém entre 10 e 25 castanhas organizadas como gomos de laranja. Ele cai de alturas de até 50 metros."},{"title":"Depende da floresta","description":"A castanheira não se reproduz em áreas desmatadas, pois depende de polinizadores e dispersores que só existem em florestas preservadas."}]'),

('vitoria-regia', 'amazonia', 'flora', 'Vitória-régia', 'Victoria amazonica', 'Aquática', 'Pouco preocupante', '🪷', '/images/flora/vitoria-regia.png', null, null,
  'A maior planta aquática do mundo, com folhas circulares de até 2,5 metros de diâmetro que podem suportar o peso de uma criança.',
  '[{"label":"Folha","value":"até 2,5 m"},{"label":"Flor","value":"Branca/rosa"},{"label":"Habitat","value":"Águas calmas"},{"label":"Distribuição","value":"Bacia amazônica"}]',
  '{"title":"Um abrigo vital nos lagos amazônicos","description":"As enormes folhas da vitória-régia criam sombra e refúgio para peixes, insetos e outros organismos aquáticos. Ela contribui para a oxigenação da água e serve como plataforma de repouso para aves e anfíbios."}',
  '[{"title":"Folha que suporta peso","description":"A estrutura nervurada na parte inferior das folhas é tão resistente que inspirou a engenharia do Crystal Palace em Londres, projetado por Joseph Paxton em 1851."},{"title":"Flor que muda de cor","description":"A flor abre branca na primeira noite e se torna rosada na segunda, atraindo diferentes polinizadores a cada fase."},{"title":"Flor aquecida","description":"A flor pode elevar sua temperatura em até 11°C acima do ambiente para volatilizar aromas e atrair besouros polinizadores durante a noite."}]'),

('acai', 'amazonia', 'flora', 'Açaí', 'Euterpe oleracea', 'Palmeira', 'Pouco preocupante', '🌴', '/images/flora/acai.png', null, null,
  'Palmeira que produz o famoso fruto açaí, base alimentar das populações ribeirinhas e hoje consumido mundialmente por seu valor nutricional.',
  '[{"label":"Altura","value":"15–25 m"},{"label":"Fruto","value":"Açaí"},{"label":"Uso","value":"Alimentício"},{"label":"Distribuição","value":"Amazônia e Mata Atlântica"}]',
  '{"title":"O pilar alimentar da Amazônia","description":"O açaí é a base da alimentação de milhões de ribeirinhos amazônicos e sustenta uma cadeia econômica que vai do extrativista ao mercado internacional. Seus frutos alimentam dezenas de espécies de aves e mamíferos na floresta."}',
  '[{"title":"Alimento milenar","description":"Populações indígenas da Amazônia consomem o açaí há milhares de anos. O nome vem do tupi \"yça-í\", que significa \"fruto que chora\"."},{"title":"Uma palmeira generosa","description":"Cada palmeira pode produzir entre 6 e 8 cachos por ano, com cada cacho pesando até 6 kg e contendo milhares de frutos."},{"title":"Rico em antioxidantes","description":"O açaí possui uma das maiores concentrações de antocianinas entre os alimentos, com poder antioxidante superior ao da uva e do mirtilo."}]'),

('seringueira', 'amazonia', 'flora', 'Seringueira', 'Hevea brasiliensis', 'Árvore', 'Pouco preocupante', '🌲', '/images/flora/seringueira.png', null, null,
  'Árvore da qual se extrai o látex para produção de borracha natural. Foi o centro do ciclo econômico da borracha no século XIX.',
  '[{"label":"Altura","value":"até 30 m"},{"label":"Produto","value":"Látex/borracha"},{"label":"Uso","value":"Industrial"},{"label":"Distribuição","value":"Amazônia"}]',
  '{"title":"A árvore que transformou a economia mundial","description":"A seringueira é a principal fonte de borracha natural do mundo, matéria-prima insubstituível para pneus de aviação e equipamentos médicos. Seu extrativismo sustentável motivou a criação de reservas extrativistas na Amazônia, protegendo milhões de hectares de floresta."}',
  '[{"title":"Ciclo da borracha","description":"No auge do ciclo da borracha (1879–1912), Manaus tornou-se uma das cidades mais ricas do mundo, com ópera, bondes elétricos e iluminação pública antes de muitas capitais europeias."},{"title":"Biopirataria histórica","description":"Em 1876, o inglês Henry Wickham contrabandeou 70 mil sementes de seringueira para a Inglaterra, levando ao colapso do monopólio brasileiro da borracha."},{"title":"Látex como defesa","description":"O látex é na verdade uma defesa da árvore contra insetos e patógenos — ao ser cortada, a seiva leitosa veda a ferida e impede infecções."}]');

-- espécies — cerrado fauna
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('lobo-guara', 'cerrado', 'fauna', 'Lobo-guará', 'Chrysocyon brachyurus', 'Mamífero', 'Quase ameaçada', '🐺', '/images/fauna/lobo-guara.png', '/images/fauna/lobo-guara-hero.png', '/images/fauna/lobo-guara-detail.png',
  'O maior canídeo da América do Sul, com pernas longas adaptadas para caminhar pela vegetação alta do Cerrado. Alimenta-se de frutos e pequenos animais.',
  '[{"label":"Altura","value":"até 90 cm"},{"label":"Dieta","value":"Onívoro"},{"label":"Habitat","value":"Campos e cerrado"},{"label":"Distribuição","value":"Brasil central e países vizinhos"}]',
  '{"title":"O jardineiro do Cerrado","description":"O lobo-guará é um dos principais dispersores de sementes do Cerrado, especialmente da lobeira (fruta-do-lobo). Ao defecar em áreas abertas, ele promove a germinação de plantas e a regeneração da vegetação nativa."}',
  '[{"title":"Não é lobo nem raposa","description":"Apesar do nome, o lobo-guará não é um lobo verdadeiro nem uma raposa. Ele é o único representante do gênero Chrysocyon, sem parentes próximos vivos."},{"title":"Urina com cheiro de maconha","description":"A urina do lobo-guará contém pirazinas, compostos que lhe conferem um cheiro forte e característico, muito semelhante ao de Cannabis, usado para marcar território."},{"title":"Estampa da nota de R$200","description":"O lobo-guará foi escolhido para estampar a cédula de R$ 200, lançada em 2020, reforçando seu papel como símbolo da fauna brasileira."}]'),

('tatu-canastra', 'cerrado', 'fauna', 'Tatu-canastra', 'Priodontes maximus', 'Mamífero', 'Vulnerável', '🦔', null, null, null,
  'O maior tatu do mundo, podendo pesar até 60 kg. Escava tocas enormes que servem de abrigo para dezenas de outras espécies.',
  '[{"label":"Peso","value":"até 60 kg"},{"label":"Dieta","value":"Insetívoro"},{"label":"Habitat","value":"Cerrado e florestas"},{"label":"Distribuição","value":"América do Sul"}]',
  '{"title":"O engenheiro de ecossistemas do Cerrado","description":"As tocas do tatu-canastra podem ter até 5 metros de profundidade e são reutilizadas por mais de 80 espécies, incluindo cobras, lagartos, raposas e corujas. Ele é considerado um engenheiro de ecossistemas por criar microhabitats essenciais."}',
  '[{"title":"Garras de escavação","description":"Suas garras dianteiras podem medir até 20 cm, as maiores proporcionalmente de qualquer animal vivente, permitindo escavar o solo com incrível eficiência."},{"title":"Fantasma do Cerrado","description":"É um animal tão discreto e noturno que muitos pesquisadores passam anos sem conseguir avistá-lo, sendo mais estudado por armadilhas fotográficas do que por observação direta."},{"title":"Consome milhares de insetos","description":"Em uma única noite de forrageamento, o tatu-canastra pode consumir dezenas de milhares de formigas e cupins, controlando naturalmente essas populações."}]'),

('seriema', 'cerrado', 'fauna', 'Seriema', 'Cariama cristata', 'Ave', 'Pouco preocupante', '🐦', '/images/fauna/seriema.png', null, null,
  'Ave terrestre de pernas longas, conhecida pelo canto alto que pode ser ouvido a quilômetros. Caça cobras e lagartos no chão do cerrado.',
  '[{"label":"Altura","value":"até 90 cm"},{"label":"Dieta","value":"Carnívoro"},{"label":"Habitat","value":"Campos abertos"},{"label":"Distribuição","value":"Brasil central e meridional"}]',
  '{"title":"A caçadora de serpentes do Cerrado","description":"A seriema desempenha um papel importante no controle de populações de cobras, lagartos e roedores nos campos do Cerrado. Sua presença indica ambientes com vegetação nativa preservada e equilíbrio ecológico."}',
  '[{"title":"Parente dos dinossauros","description":"A seriema é uma das aves viventes mais próximas dos extintos pássaros do terror (Phorusrhacidae), predadores gigantes que dominaram a América do Sul há milhões de anos."},{"title":"Técnica de caça engenhosa","description":"Para matar cobras e lagartos, a seriema os agarra com o bico e os arremessa violentamente contra pedras ou o chão, repetidas vezes, até que estejam mortos."},{"title":"Canto de alerta","description":"Seu canto estridente pode ser ouvido a mais de 3 km de distância e é frequentemente utilizado como alarme matinal por moradores de áreas rurais."}]'),

('tamanduá-bandeira', 'cerrado', 'fauna', 'Tamanduá-bandeira', 'Myrmecophaga tridactyla', 'Mamífero', 'Vulnerável', '🐾', '/images/fauna/tamandua-bandeira.png', null, null,
  'Mamífero com língua de até 60 cm que pode consumir 30 mil formigas por dia. Sua cauda funciona como cobertor durante o sono.',
  '[{"label":"Peso","value":"até 45 kg"},{"label":"Dieta","value":"Insetívoro"},{"label":"Habitat","value":"Campos e cerrado"},{"label":"Distribuição","value":"América Central e do Sul"}]',
  '{"title":"O regulador natural de insetos","description":"O tamanduá-bandeira é fundamental para o controle de populações de formigas e cupins no Cerrado. Ao abrir cupinzeiros e formigueiros, também facilita o acesso de outras espécies a esses recursos e promove a aeração do solo."}',
  '[{"title":"Língua de 60 cm","description":"Sua língua pode se projetar e retrair até 150 vezes por minuto, coberta por uma saliva extremamente pegajosa que captura centenas de insetos a cada lambida."},{"title":"Abraço mortal","description":"Quando ameaçado, o tamanduá se ergue sobre as patas traseiras e abraça o predador com suas garras poderosas — há registros de tamanduás matando onças dessa forma."},{"title":"Cauda-cobertor","description":"Sua enorme cauda felpuda serve como cobertor durante o sono, protegendo o corpo do frio e de insetos, além de ajudar na camuflagem em meio à vegetação."}]');

-- espécies — cerrado flora
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('ipê-amarelo', 'cerrado', 'flora', 'Ipê-amarelo', 'Handroanthus albus', 'Árvore', 'Pouco preocupante', '🌼', '/images/flora/ipe-amarelo.png', null, null,
  'Árvore-símbolo do Brasil, cujas flores amarelas cobrem completamente a copa durante o inverno, antes das novas folhas surgirem.',
  '[{"label":"Altura","value":"6–14 m"},{"label":"Floração","value":"Jun–Set"},{"label":"Uso","value":"Ornamental"},{"label":"Distribuição","value":"Cerrado e Mata Atlântica"}]',
  '{"title":"Um símbolo de resistência e beleza","description":"O ipê-amarelo floresce justamente na estação seca, quando a maioria das plantas está sem folhas, fornecendo néctar e pólen essenciais para abelhas e beija-flores nesse período de escassez. É amplamente utilizado em arborização urbana e projetos de recuperação ambiental."}',
  '[{"title":"Flor nacional","description":"O ipê-amarelo é considerado a flor nacional do Brasil, embora nunca tenha sido oficializado por lei federal. Foi declarado assim por decreto do presidente Jânio Quadros em 1961."},{"title":"Madeira nobre","description":"A madeira do ipê é uma das mais densas e resistentes do Brasil, sendo praticamente imune a cupins e amplamente usada em decks, pergolados e construção naval."},{"title":"Floração sincronizada","description":"Todos os ipês de uma região florescem quase ao mesmo tempo, criando um espetáculo visual que dura apenas 5 a 7 dias antes das pétalas caírem."}]'),

('pequi', 'cerrado', 'flora', 'Pequi', 'Caryocar brasiliense', 'Árvore', 'Pouco preocupante', '🫒', '/images/flora/pequizeiro.png', '/images/flora/pequizeiro-hero.png', '/images/flora/pequizeiro-detail.png',
  'Fruto emblemático da culinária do Cerrado. A árvore tem casca grossa resistente ao fogo, adaptação típica da vegetação do bioma.',
  '[{"label":"Altura","value":"até 10 m"},{"label":"Fruto","value":"Pequi"},{"label":"Uso","value":"Alimentício"},{"label":"Distribuição","value":"Cerrado brasileiro"}]',
  '{"title":"O tesouro culinário do Cerrado","description":"O pequi é uma espécie-chave para a cultura e economia das comunidades do Cerrado, gerando renda para milhares de famílias extrativistas. Seus frutos alimentam aves, mamíferos e insetos, e sua casca grossa permite sobreviver às queimadas naturais do bioma."}',
  '[{"title":"Nunca morda o pequi","description":"O caroço do pequi é coberto por espinhos finíssimos que podem se cravar na língua e nos lábios. Por isso, o fruto é sempre raspado com os dentes, nunca mordido."},{"title":"Aroma inconfundível","description":"O cheiro forte do pequi é tão marcante que divide opiniões — é adorado no Cerrado e estranhado em outras regiões. O aroma vem de compostos voláteis que também atraem morcegos polinizadores."},{"title":"Resistente ao fogo","description":"A casca suberosa do pequizeiro pode ter mais de 5 cm de espessura, protegendo o câmbio vascular das queimadas que ciclicamente varrem o Cerrado."}]'),

('buriti', 'cerrado', 'flora', 'Buriti', 'Mauritia flexuosa', 'Palmeira', 'Pouco preocupante', '🌴', '/images/flora/buriti.png', null, null,
  'A "árvore da vida" do Cerrado, encontrada nas veredas. Seus frutos alimentam dezenas de espécies, e do tronco se extrai fibra e palmito.',
  '[{"label":"Altura","value":"até 30 m"},{"label":"Fruto","value":"Buriti"},{"label":"Habitat","value":"Veredas"},{"label":"Importância","value":"Alimento e artesanato"}]',
  '{"title":"A árvore da vida nas veredas do Cerrado","description":"O buriti é uma espécie-chave das veredas, ambientes úmidos do Cerrado que funcionam como nascentes e corredores ecológicos. Seus frutos alimentam araras, emas, antas e dezenas de outras espécies. Praticamente todas as partes da planta são aproveitadas pelas comunidades locais."}',
  '[{"title":"Uso integral","description":"Das folhas se extrai fibra para artesanato, do tronco vem palmito e farinha, dos frutos se faz doce, óleo e sorvete, e da medula se produz uma espécie de cortiça — nada se desperdiça."},{"title":"Indicador de água","description":"A presença de buritizais sempre indica lençol freático superficial ou cursos d''água, sendo usada por viajantes do sertão como guia para encontrar fontes de água."},{"title":"Maior palmeira do Cerrado","description":"O buriti pode atingir 30 metros de altura e viver por mais de 200 anos, dominando a paisagem das veredas com suas copas em forma de leque."}]'),

('barbatimao', 'cerrado', 'flora', 'Barbatimão', 'Stryphnodendron adstringens', 'Árvore', 'Pouco preocupante', '🌿', null, null, null,
  'Árvore medicinal do Cerrado, com casca rica em taninos usada no tratamento de feridas e inflamações pela medicina popular.',
  '[{"label":"Altura","value":"4–5 m"},{"label":"Uso","value":"Medicinal"},{"label":"Habitat","value":"Cerrado típico"},{"label":"Importância","value":"Fitoterapia"}]',
  '{"title":"A farmácia natural do Cerrado","description":"O barbatimão é uma das plantas medicinais mais estudadas do Brasil, com eficácia comprovada cientificamente no tratamento de feridas, inflamações e infecções. Sua casca é utilizada há séculos por comunidades tradicionais e hoje é incorporada em produtos fitoterápicos."}',
  '[{"title":"Comprovado pela ciência","description":"Estudos científicos confirmaram que os taninos da casca do barbatimão possuem propriedades cicatrizantes, anti-inflamatórias e antimicrobianas, validando o conhecimento popular."},{"title":"Curtimento natural","description":"Os taninos do barbatimão eram utilizados para curtir couro de forma artesanal, substituindo produtos químicos industriais em comunidades rurais."},{"title":"Resistente ao fogo","description":"Como muitas plantas do Cerrado, o barbatimão possui casca espessa e raízes profundas que permitem rebrotar rapidamente após queimadas."}]');

-- espécies — mata atlântica fauna
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('mico-leao-dourado', 'mata-atlantica', 'fauna', 'Mico-leão-dourado', 'Leontopithecus rosalia', 'Mamífero', 'Em perigo', '🐒', null, null, null,
  'Primata endêmico da Mata Atlântica fluminense, símbolo da conservação no Brasil. Quase foi extinto nos anos 1970, com menos de 200 indivíduos restantes.',
  '[{"label":"Peso","value":"500–700 g"},{"label":"Dieta","value":"Onívoro"},{"label":"Habitat","value":"Floresta de baixada"},{"label":"Distribuição","value":"Rio de Janeiro"}]',
  '{"title":"O símbolo da conservação brasileira","description":"O mico-leão-dourado é o maior caso de sucesso de conservação do Brasil. Programas de reprodução em cativeiro e reintrodução elevaram a população de menos de 200 para cerca de 3.700 indivíduos. Ele é um dispersor de sementes essencial para a regeneração da Mata Atlântica de baixada."}',
  '[{"title":"Quase desapareceu","description":"Na década de 1970, restavam menos de 200 micos-leões-dourados na natureza. Graças a programas de conservação internacionais, a população se recuperou significativamente."},{"title":"Crina de leão","description":"A juba dourada que circunda seu rosto não é apenas ornamental — serve para parecer maior diante de predadores e rivais, dando ao primata uma aparência semelhante à de um pequeno leão."},{"title":"Família unida","description":"Os micos vivem em grupos familiares nos quais o pai carrega os filhotes nas costas durante as primeiras semanas, dividindo os cuidados parentais com a mãe."}]'),

('muriqui', 'mata-atlantica', 'fauna', 'Muriqui-do-norte', 'Brachyteles hypoxanthus', 'Mamífero', 'Criticamente em perigo', '🦧', null, null, null,
  'O maior primata das Américas, conhecido como "mono-carvoeiro". Restam menos de 1.000 indivíduos na natureza.',
  '[{"label":"Peso","value":"até 15 kg"},{"label":"Dieta","value":"Herbívoro"},{"label":"Habitat","value":"Floresta montana"},{"label":"Distribuição","value":"Minas Gerais e Espírito Santo"}]',
  '{"title":"O gigante pacífico da Mata Atlântica","description":"O muriqui é essencial para a dispersão de sementes de árvores de grande porte na Mata Atlântica. Sua sociedade pacífica e igualitária — sem hierarquia de dominância — é única entre os primatas e objeto de estudo da primatologia mundial."}',
  '[{"title":"Primata pacifista","description":"Diferente de outros primatas, os muriquis não possuem hierarquia de dominância e raramente exibem agressão. Conflitos são resolvidos com abraços, não com brigas."},{"title":"Abraços de grupo","description":"Os muriquis se cumprimentam com longos abraços coletivos, entrelaçando braços e caudas em um comportamento social único entre os primatas."},{"title":"Maior primata das Américas","description":"Com até 15 kg e braços longos que permitem braquiação entre as árvores, o muriqui é o maior primata do continente americano."}]'),

('tucano-de-bico-preto', 'mata-atlantica', 'fauna', 'Tucano-de-bico-preto', 'Ramphastos vitellinus', 'Ave', 'Vulnerável', '🦜', null, null, null,
  'Ave icônica com bico colorido que pode chegar a 20 cm. Importante dispersor de sementes na Mata Atlântica.',
  '[{"label":"Tamanho","value":"45–48 cm"},{"label":"Dieta","value":"Frugívoro"},{"label":"Habitat","value":"Dossel florestal"},{"label":"Distribuição","value":"Mata Atlântica costeira"}]',
  '{"title":"O plantador de árvores da floresta","description":"O tucano é um dos maiores dispersores de sementes da Mata Atlântica, engolindo frutos inteiros e depositando as sementes intactas longe da planta-mãe. Sem ele, muitas espécies de árvores de grande porte teriam dificuldade para se reproduzir."}',
  '[{"title":"Bico termorregulador","description":"O grande bico do tucano é ricamente vascularizado e funciona como um radiador térmico, ajudando a regular a temperatura corporal em climas quentes."},{"title":"Dorme de forma compacta","description":"Para dormir, o tucano gira a cabeça para trás e encaixa o bico entre as penas das costas, dobrando a cauda sobre o corpo para caber em ocos de árvores."},{"title":"Bico leve e resistente","description":"Apesar de parecer pesado, o bico do tucano é oco e extremamente leve, composto por trabéculas de queratina que lhe dão resistência com pouco peso."}]'),

('jaguatirica', 'mata-atlantica', 'fauna', 'Jaguatirica', 'Leopardus pardalis', 'Mamífero', 'Pouco preocupante', '🐱', null, null, null,
  'Felino de porte médio com pelagem manchada. É o terceiro maior gato das Américas e excelente caçador noturno.',
  '[{"label":"Peso","value":"8–16 kg"},{"label":"Dieta","value":"Carnívoro"},{"label":"Habitat","value":"Florestas densas"},{"label":"Distribuição","value":"Américas"}]',
  '{"title":"A predadora silenciosa da Mata Atlântica","description":"A jaguatirica é um mesopredador essencial para o equilíbrio da Mata Atlântica, controlando populações de roedores, aves e répteis. Sua presença indica fragmentos florestais com qualidade suficiente para manter cadeias tróficas complexas."}',
  '[{"title":"Visão noturna superior","description":"Seus olhos são até 6 vezes mais sensíveis à luz do que os humanos, permitindo caçar com eficiência em noites sem luar na floresta densa."},{"title":"Pelagem de alta-costura","description":"A beleza de sua pelagem manchada a tornou alvo do comércio ilegal de peles no século XX, quando milhares de jaguatiricas eram caçadas anualmente para a indústria da moda."},{"title":"Solitária por natureza","description":"Cada jaguatirica mantém um território de até 15 km² que patrulha solitariamente, marcando-o com urina e arranhões em árvores."}]');

-- espécies — mata atlântica flora
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('pau-brasil', 'mata-atlantica', 'flora', 'Pau-brasil', 'Paubrasilia echinata', 'Árvore', 'Em perigo', '🪵', null, null, null,
  'A árvore que deu nome ao país. Sua madeira vermelha era explorada desde a colonização e hoje é protegida por lei.',
  '[{"label":"Altura","value":"até 15 m"},{"label":"Uso","value":"Histórico/madeira"},{"label":"Floração","value":"Set–Out"},{"label":"Distribuição","value":"Mata Atlântica costeira"}]',
  '{"title":"A árvore que batizou uma nação","description":"O pau-brasil é uma das espécies mais importantes da história do Brasil. Sua exploração predatória durante a colonização quase levou à extinção, mas hoje programas de reflorestamento e proteção legal buscam recuperar suas populações na Mata Atlântica."}',
  '[{"title":"Origem do nome Brasil","description":"O país recebeu seu nome por causa desta árvore. \"Brasil\" vem de \"brasa\", referência à cor vermelha intensa da madeira, semelhante a brasas vivas."},{"title":"Arcos de violino","description":"A madeira do pau-brasil é considerada a melhor do mundo para fabricação de arcos de violino e outros instrumentos de corda, sendo altamente valorizada por luthiers."},{"title":"Corante natural","description":"Antes dos corantes sintéticos, o pau-brasil era a principal fonte do pigmento vermelho usado para tingir tecidos na Europa, sendo o motor econômico da colonização."}]'),

('jussara', 'mata-atlantica', 'flora', 'Palmito-juçara', 'Euterpe edulis', 'Palmeira', 'Vulnerável', '🌴', null, null, null,
  'Palmeira ameaçada pela extração predatória do palmito. Seus frutos são similares ao açaí e essenciais para aves como tucanos.',
  '[{"label":"Altura","value":"até 15 m"},{"label":"Fruto","value":"Juçara"},{"label":"Uso","value":"Alimentício"},{"label":"Distribuição","value":"Mata Atlântica"}]',
  '{"title":"Uma palmeira vital para a floresta e para as comunidades","description":"A juçara é uma espécie-chave da Mata Atlântica: seus frutos alimentam mais de 70 espécies de aves e mamíferos. A transição da extração de palmito (que mata a planta) para o uso sustentável dos frutos (similar ao açaí) oferece uma alternativa econômica que conserva a espécie."}',
  '[{"title":"Palmito que mata a planta","description":"Diferente do açaí, a juçara não rebrota após a extração do palmito, pois possui apenas um estipe. Cada palmito consumido representa uma palmeira morta."},{"title":"Açaí da Mata Atlântica","description":"Os frutos da juçara são nutricionalmente idênticos ao açaí amazônico e cada vez mais usados na produção de polpa, gerando renda sem derrubar a palmeira."},{"title":"Banquete para tucanos","description":"Tucanos e jacutingas dependem dos frutos da juçara como fonte principal de alimento em determinadas épocas do ano. O declínio da palmeira ameaça diretamente essas aves."}]'),

('bromélia-imperial', 'mata-atlantica', 'flora', 'Bromélia-imperial', 'Alcantarea imperialis', 'Bromélia', 'Vulnerável', '🌺', null, null, null,
  'A maior bromélia do Brasil, endêmica das montanhas do Rio de Janeiro. Pode atingir 1,5 metro de diâmetro.',
  '[{"label":"Tamanho","value":"até 1,5 m"},{"label":"Habitat","value":"Afloramentos rochosos"},{"label":"Uso","value":"Ornamental"},{"label":"Distribuição","value":"Serra dos Órgãos (RJ)"}]',
  '{"title":"Um reservatório de vida nas alturas","description":"A bromélia-imperial acumula água entre suas folhas, formando pequenas piscinas que servem de habitat para girinos, larvas de insetos e microorganismos. Em afloramentos rochosos onde não há solo, ela é a principal fonte de vida e umidade."}',
  '[{"title":"Floresce uma única vez","description":"Após décadas de crescimento, a bromélia-imperial produz uma haste floral de até 3 metros de altura. Depois da floração e frutificação, a planta morre, mas deixa brotos laterais."},{"title":"Sobrevive sem solo","description":"Cresce diretamente sobre rochas expostas em altitudes acima de 1.000 metros, obtendo nutrientes apenas da água da chuva e de detritos orgânicos que se acumulam entre suas folhas."},{"title":"Jardim vertical natural","description":"Um único exemplar pode abrigar centenas de organismos, desde algas e bactérias até rãs e salamandras, funcionando como um verdadeiro ecossistema miniatura."}]'),

('ipê-roxo', 'mata-atlantica', 'flora', 'Ipê-roxo', 'Handroanthus impetiginosus', 'Árvore', 'Pouco preocupante', '💜', null, null, null,
  'Árvore de grande porte com floração exuberante em tons de rosa e roxo. Sua madeira é uma das mais resistentes do Brasil.',
  '[{"label":"Altura","value":"até 20 m"},{"label":"Floração","value":"Jul–Set"},{"label":"Uso","value":"Ornamental/madeira"},{"label":"Distribuição","value":"Mata Atlântica e Cerrado"}]',
  '{"title":"Beleza e recursos para a floresta","description":"O ipê-roxo é um importante recurso para polinizadores durante a estação seca, quando poucas espécies florescem. Sua madeira extremamente densa e durável é uma das mais valorizadas da silvicultura brasileira, sendo usada em construções que precisam resistir por décadas."}',
  '[{"title":"Lapacho medicinal","description":"A casca interna do ipê-roxo contém lapachol, uma substância com propriedades anti-inflamatórias e antimicrobianas estudada como potencial agente anticancerígeno."},{"title":"Madeira quase eterna","description":"A madeira do ipê é tão densa que afunda na água. Decks e estruturas feitas com essa madeira podem durar mais de 25 anos expostos ao tempo sem tratamento químico."},{"title":"Floração sincronizada","description":"Assim como o ipê-amarelo, o ipê-roxo perde todas as folhas antes de florescer, criando um espetáculo de cores que transforma paisagens urbanas e rurais por poucos dias."}]');

-- espécies — caatinga fauna
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('ararinha-azul', 'caatinga', 'fauna', 'Ararinha-azul', 'Cyanopsitta spixii', 'Ave', 'Extinta na natureza', '🦜', null, null, null,
  'Ave endêmica da Caatinga baiana, declarada extinta na natureza em 2000. Programas de reintrodução tentam trazê-la de volta ao habitat original.',
  '[{"label":"Tamanho","value":"55 cm"},{"label":"Dieta","value":"Frugívoro"},{"label":"Habitat","value":"Caatinga arbórea"},{"label":"Distribuição","value":"Norte da Bahia (histórica)"}]',
  '{"title":"Um símbolo da luta contra a extinção","description":"A ararinha-azul tornou-se o símbolo mundial da conservação de aves ameaçadas. Programas internacionais de reprodução em cativeiro e reintrodução na Caatinga baiana representam um dos maiores esforços de conservação da história, buscando reverter a extinção na natureza."}',
  '[{"title":"Inspirou um filme","description":"A ararinha-azul inspirou o filme de animação \"Rio\" (2011), da Blue Sky Studios, que conta a história de um macho criado em cativeiro que viaja ao Brasil."},{"title":"Último indivíduo selvagem","description":"O último exemplar selvagem conhecido era um macho que viveu sozinho na Caatinga baiana até desaparecer em outubro de 2000, marcando a extinção na natureza."},{"title":"Reintrodução em andamento","description":"Desde 2022, exemplares criados em cativeiro estão sendo soltos na região de Curaçá, Bahia, em um programa que busca restabelecer uma população viável na natureza."}]'),

('tatu-bola', 'caatinga', 'fauna', 'Tatu-bola', 'Tolypeutes tricinctus', 'Mamífero', 'Em perigo', '⚽', null, null, null,
  'Mascote da Copa do Mundo de 2014, este tatu é o único que se enrola completamente em uma bola como mecanismo de defesa.',
  '[{"label":"Peso","value":"1–1,8 kg"},{"label":"Dieta","value":"Insetívoro"},{"label":"Habitat","value":"Caatinga"},{"label":"Distribuição","value":"Nordeste do Brasil"}]',
  '{"title":"O pequeno guardião da Caatinga","description":"O tatu-bola é endêmico do Brasil e sua conservação depende diretamente da preservação da Caatinga. Ele ajuda no controle de populações de formigas e cupins e na aeração do solo ao escavar em busca de alimento."}',
  '[{"title":"Mascote da Copa","description":"O tatu-bola foi escolhido como mascote da Copa do Mundo FIFA 2014, recebendo o nome \"Fuleco\" (fusão de futebol e ecologia), para chamar atenção à conservação da espécie."},{"title":"Defesa perfeita","description":"É o único tatu capaz de se enrolar completamente em uma esfera, protegendo toda a parte mole do corpo com a carapaça. A forma esférica não deixa nenhuma fresta para predadores."},{"title":"Não escava tocas","description":"Diferente de outros tatus, o tatu-bola não cava suas próprias tocas, preferindo usar tocas abandonadas ou se abrigar sob arbustos e pedras."}]'),

('calango', 'caatinga', 'fauna', 'Calango', 'Tropidurus hispidus', 'Réptil', 'Pouco preocupante', '🦎', null, null, null,
  'Lagarto abundante na Caatinga, adaptado ao calor intenso. É um importante controlador de insetos no ecossistema.',
  '[{"label":"Tamanho","value":"15–25 cm"},{"label":"Dieta","value":"Insetívoro"},{"label":"Habitat","value":"Áreas rochosas"},{"label":"Distribuição","value":"Nordeste e Centro-Oeste"}]',
  '{"title":"O controlador de pragas do sertão","description":"O calango é um dos mais eficientes controladores naturais de insetos na Caatinga, consumindo grandes quantidades de formigas, cupins, moscas e baratas diariamente. Também serve como presa para aves de rapina e serpentes, sendo um elo fundamental na cadeia alimentar."}',
  '[{"title":"Banho de sol obrigatório","description":"Como réptil ectotérmico, o calango precisa se aquecer ao sol toda manhã antes de ter energia para caçar. Rochas expostas são seus pontos favoritos de termorregulação."},{"title":"Flexões territoriais","description":"Os machos fazem movimentos de flexão (push-ups) com as patas dianteiras para marcar território e atrair fêmeas — quanto mais vigorosas as flexões, mais dominante o macho."},{"title":"Cauda regenerável","description":"Quando capturado por um predador, o calango pode soltar a cauda, que continua se movendo e distraindo o atacante enquanto o lagarto foge. A cauda se regenera em algumas semanas."}]'),

('mocó', 'caatinga', 'fauna', 'Mocó', 'Kerodon rupestris', 'Mamífero', 'Pouco preocupante', '🐹', null, null, null,
  'Roedor que vive entre rochas na Caatinga. É ágil escalador e se alimenta de folhas e cascas de árvores.',
  '[{"label":"Peso","value":"até 1 kg"},{"label":"Dieta","value":"Herbívoro"},{"label":"Habitat","value":"Afloramentos rochosos"},{"label":"Distribuição","value":"Nordeste do Brasil"}]',
  '{"title":"O escalador das rochas da Caatinga","description":"O mocó desempenha um papel importante na dispersão de sementes entre afloramentos rochosos da Caatinga. Seus excrementos depositados nas frestas das rochas fertilizam o substrato e criam condições para o crescimento de plantas em ambientes que seriam estéreis."}',
  '[{"title":"Parente da capivara","description":"Apesar do tamanho pequeno, o mocó é parente das capivaras e dos porquinhos-da-índia, pertencendo à família dos caviídeos (Caviidae)."},{"title":"Escalador nato","description":"Suas patas possuem almofadas aderentes que permitem escalar rochas verticais e até superfícies lisas com agilidade surpreendente, escapando de predadores com facilidade."},{"title":"Sobrevive sem beber água","description":"O mocó obtém toda a água necessária das folhas e cascas que consome, sendo capaz de sobreviver longos períodos sem acesso direto à água — adaptação vital na Caatinga."}]');

-- espécies — caatinga flora
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('mandacaru', 'caatinga', 'flora', 'Mandacaru', 'Cereus jamacaru', 'Cactácea', 'Pouco preocupante', '🌵', null, null, null,
  'O cacto-símbolo da Caatinga, que pode atingir 6 metros de altura. Armazena água em seu caule e serve de alimento para animais na seca.',
  '[{"label":"Altura","value":"até 6 m"},{"label":"Flor","value":"Branca (noturna)"},{"label":"Uso","value":"Alimentação animal"},{"label":"Distribuição","value":"Semiárido nordestino"}]',
  '{"title":"O reservatório de vida do semiárido","description":"O mandacaru é uma espécie vital para a sobrevivência da fauna na Caatinga durante a seca. Seu caule suculento armazena grande quantidade de água, servindo de alimento e hidratação para aves, morcegos, lagartos e insetos quando outras fontes se esgotam."}',
  '[{"title":"Previsão do tempo sertaneja","description":"Na cultura popular nordestina, quando o mandacaru floresce fora de época, é sinal de que a chuva está próxima — uma tradição imortalizada na música de Luiz Gonzaga."},{"title":"Flor de uma noite","description":"As grandes flores brancas do mandacaru se abrem apenas durante a noite e murcham ao nascer do sol, sendo polinizadas por morcegos e mariposas noturnas."},{"title":"Cerca viva natural","description":"No sertão, o mandacaru é plantado em fileiras para formar cercas vivas naturais, aproveitando seus espinhos como barreira contra animais."}]'),

('umbuzeiro', 'caatinga', 'flora', 'Umbuzeiro', 'Spondias tuberosa', 'Árvore', 'Pouco preocupante', '🌳', null, null, null,
  'Árvore sagrada do sertão, chamada de "árvore da vida" por armazenar água em raízes tuberosas, garantindo sobrevivência na seca.',
  '[{"label":"Altura","value":"4–7 m"},{"label":"Fruto","value":"Umbu"},{"label":"Uso","value":"Alimentício"},{"label":"Importância","value":"Segurança hídrica e alimentar"}]',
  '{"title":"A árvore sagrada do sertão","description":"O umbuzeiro é considerado sagrado pelos sertanejos por garantir alimento e água nos períodos mais severos de seca. Suas raízes tuberosas armazenam até 3 mil litros de água, e seus frutos sustentam famílias inteiras. Euclides da Cunha o chamou de \"árvore sagrada do sertão\" em Os Sertões."}',
  '[{"title":"Raízes-reservatório","description":"As raízes do umbuzeiro formam xilopódios — tubérculos que armazenam água e nutrientes. Uma árvore adulta pode ter até 3 mil litros de reserva hídrica subterrânea."},{"title":"Citado por Euclides da Cunha","description":"Em \"Os Sertões\" (1902), Euclides da Cunha dedica parágrafos ao umbuzeiro, chamando-o de \"árvore sagrada\" e descrevendo como sertanejos sobreviviam graças a ela."},{"title":"Umbuzada nutritiva","description":"A umbuzada — bebida feita com umbu, leite e açúcar — é um alimento tradicional do sertão que fornece energia e hidratação, sendo consumida há séculos pelos nordestinos."}]'),

('xique-xique', 'caatinga', 'flora', 'Xique-xique', 'Pilosocereus gounellei', 'Cactácea', 'Pouco preocupante', '🌵', null, null, null,
  'Cacto ramificado comum na Caatinga, é uma importante fonte de água e alimento para animais durante os períodos de seca.',
  '[{"label":"Altura","value":"até 3 m"},{"label":"Habitat","value":"Solo pedregoso"},{"label":"Uso","value":"Alimentação animal"},{"label":"Distribuição","value":"Semiárido nordestino"}]',
  '{"title":"Fonte de vida no solo mais árido","description":"O xique-xique é uma das poucas plantas que sobrevive nos solos mais secos e pedregosos da Caatinga. Serve como reservatório de água e alimento para o gado e fauna silvestre durante as secas prolongadas, e suas flores alimentam polinizadores essenciais."}',
  '[{"title":"Nome onomatopeico","description":"O nome \"xique-xique\" imita o som que os espinhos fazem ao roçar uns nos outros quando o vento sopra, segundo a tradição popular nordestina."},{"title":"Alimento de emergência","description":"Em secas severas, os sertanejos queimam os espinhos do xique-xique e cortam o caule para alimentar o gado com a polpa suculenta — prática que já salvou rebanhos inteiros."},{"title":"Abrigo de corujas","description":"Espécies de corujas-buraqueiras frequentemente nidificam na base de xique-xiques densos, aproveitando a proteção dos espinhos contra predadores."}]'),

('catingueira', 'caatinga', 'flora', 'Catingueira', 'Poincianella pyramidalis', 'Árvore', 'Pouco preocupante', '🌿', null, null, null,
  'Uma das árvores mais comuns da Caatinga. Perde as folhas na seca e reverdece rapidamente com as primeiras chuvas.',
  '[{"label":"Altura","value":"4–8 m"},{"label":"Uso","value":"Medicinal/lenha"},{"label":"Adaptação","value":"Caducifólia"},{"label":"Distribuição","value":"Caatinga nordestina"}]',
  '{"title":"A pioneira na recuperação da Caatinga","description":"A catingueira é uma das primeiras espécies a colonizar áreas degradadas da Caatinga, preparando o solo para outras plantas. Sua capacidade de perder folhas na seca (caducifolia) reduz a perda de água e deposita matéria orgânica no solo, enriquecendo-o."}',
  '[{"title":"Deu nome ao bioma","description":"O nome \"Caatinga\" vem do tupi \"caa\" (mata) + \"tinga\" (branca), referência à aparência esbranquiçada da vegetação quando árvores como a catingueira perdem as folhas na seca."},{"title":"Reverdece em horas","description":"Após as primeiras chuvas, a catingueira pode emitir folhas novas em questão de horas, transformando a paisagem cinza do sertão em verde vibrante quase da noite para o dia."},{"title":"Chá medicinal","description":"Na medicina popular nordestina, o chá da casca da catingueira é utilizado para tratar inflamações, gripes e problemas digestivos, com eficácia reconhecida por comunidades há gerações."}]');

-- espécies — pampa fauna
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('veado-campeiro', 'pampa', 'fauna', 'Veado-campeiro', 'Ozotoceros bezoarticus', 'Mamífero', 'Quase ameaçada', '🦌', null, null, null,
  'O único cervídeo que vive exclusivamente em campos abertos no Brasil. Sua população diminuiu drasticamente com a conversão dos campos nativos.',
  '[{"label":"Peso","value":"30–40 kg"},{"label":"Dieta","value":"Herbívoro"},{"label":"Habitat","value":"Campos nativos"},{"label":"Distribuição","value":"Sul e Centro-Oeste do Brasil"}]',
  '{"title":"O símbolo dos campos nativos ameaçados","description":"O veado-campeiro é um indicador da saúde dos campos nativos do Pampa. Sua presença sinaliza áreas com vegetação campestre preservada. O pastejo seletivo contribui para a manutenção da diversidade de gramíneas e a reciclagem de nutrientes no solo."}',
  '[{"title":"Glândula de cheiro","description":"Os machos possuem uma glândula odorífera entre os cascos que libera um cheiro forte, usado para marcar território e atrair fêmeas durante o período reprodutivo."},{"title":"Chifres ramificados","description":"Os machos possuem chifres com até três ramificações que são trocados anualmente. Os chifres novos crescem cobertos por veludo vascularizado."},{"title":"Corredor veloz","description":"Em campos abertos, o veado-campeiro pode atingir velocidades de até 70 km/h em corridas curtas, sendo um dos mamíferos mais rápidos do Brasil."}]'),

('graxaim', 'pampa', 'fauna', 'Graxaim-do-campo', 'Lycalopex gymnocercus', 'Mamífero', 'Pouco preocupante', '🦊', null, null, null,
  'Canídeo típico dos campos do sul, com hábitos crepusculares. É um importante dispersor de sementes no Pampa.',
  '[{"label":"Peso","value":"4–7 kg"},{"label":"Dieta","value":"Onívoro"},{"label":"Habitat","value":"Campos abertos"},{"label":"Distribuição","value":"Sul do Brasil e países vizinhos"}]',
  '{"title":"O dispersor de sementes dos campos sulinos","description":"O graxaim é um importante dispersor de sementes de frutas nativas nos campos do Pampa. Ao consumir frutos como pitanga, araçá e butiá e depositar as sementes em seus excrementos, ele contribui para a regeneração da vegetação nativa e a conectividade entre fragmentos de campo."}',
  '[{"title":"Raposa que não é raposa","description":"Apesar de ser chamado popularmente de raposa, o graxaim não pertence ao gênero Vulpes das raposas verdadeiras. Ele faz parte do gênero Lycalopex, exclusivo da América do Sul."},{"title":"Caçador oportunista","description":"O graxaim come praticamente de tudo: frutas, insetos, roedores, aves, ovos, répteis e até carniça. Essa versatilidade alimentar explica sua ampla distribuição."},{"title":"Parceiro do quero-quero","description":"O quero-quero frequentemente dá o alarme quando o graxaim se aproxima, alertando outras aves e animais. Essa relação involuntária beneficia todo o ecossistema campestre."}]'),

('joao-de-barro', 'pampa', 'fauna', 'João-de-barro', 'Furnarius rufus', 'Ave', 'Pouco preocupante', '🐦', null, null, null,
  'Ave que constrói ninhos de barro em formato de forno. É uma das aves mais conhecidas do sul do Brasil.',
  '[{"label":"Tamanho","value":"18–20 cm"},{"label":"Dieta","value":"Insetívoro"},{"label":"Ninho","value":"Barro/argila"},{"label":"Distribuição","value":"Sul e Sudeste do Brasil"}]',
  '{"title":"O arquiteto que constrói para todos","description":"Os ninhos abandonados do joão-de-barro são reutilizados por dezenas de espécies — corujas, periquitos, morcegos, vespas e até pequenas serpentes. Ele é um verdadeiro engenheiro de ecossistemas, criando abrigos que aumentam a biodiversidade local."}',
  '[{"title":"Ninho à prova de chuva","description":"O ninho de barro tem formato de forno com entrada lateral e um anteparo interno que protege os ovos do vento e da chuva. Pode pesar até 5 kg quando seco."},{"title":"Construção em casal","description":"Macho e fêmea constroem o ninho juntos, carregando centenas de bolotas de barro misturado com esterco e fibras. A obra leva de 15 a 20 dias para ficar pronta."},{"title":"Nunca repete o ninho","description":"A cada estação reprodutiva, o casal constrói um ninho novo, geralmente no topo do antigo. Postes e árvores podem acumular vários ninhos empilhados ao longo dos anos."}]'),

('quero-quero', 'pampa', 'fauna', 'Quero-quero', 'Vanellus chilensis', 'Ave', 'Pouco preocupante', '🐤', null, null, null,
  'Ave territorial que avisa com gritos estridentes quando alguém se aproxima. É considerada a sentinela dos campos.',
  '[{"label":"Tamanho","value":"35–40 cm"},{"label":"Dieta","value":"Onívoro"},{"label":"Habitat","value":"Campos e áreas abertas"},{"label":"Distribuição","value":"América do Sul"}]',
  '{"title":"A sentinela alerta dos campos","description":"O quero-quero funciona como um sistema de alarme natural nos campos do Pampa. Seus gritos de alerta avisam outras aves e mamíferos sobre a presença de predadores, beneficiando toda a comunidade animal. Também é um importante controlador de insetos e larvas nos pastos."}',
  '[{"title":"Nome que imita o canto","description":"O nome \"quero-quero\" é uma onomatopeia do seu grito estridente. Em espanhol, é chamado de \"tero-tero\" pelo mesmo motivo."},{"title":"Defensor feroz","description":"Para proteger o ninho, o quero-quero finge estar machucado para atrair predadores para longe dos ovos. Se isso não funciona, ataca com esporões pontiagudos nas asas."},{"title":"Ninho no chão","description":"O quero-quero faz ninhos simples diretamente no solo, em campos abertos. Os filhotes são precoces — saem andando e se alimentando sozinhos poucas horas após nascerem."}]');

-- espécies — pampa flora
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('capim-barba-de-bode', 'pampa', 'flora', 'Capim-barba-de-bode', 'Aristida jubata', 'Gramínea', 'Pouco preocupante', '🌾', null, null, null,
  'Gramínea nativa que forma extensos tufos nos campos do Pampa. É indicadora de campos bem conservados.',
  '[{"label":"Altura","value":"30–60 cm"},{"label":"Habitat","value":"Campos secos"},{"label":"Tipo","value":"Perene"},{"label":"Importância","value":"Indicadora ecológica"}]',
  '{"title":"A guardiã dos campos nativos","description":"O capim-barba-de-bode é uma espécie indicadora de campos nativos bem conservados no Pampa. Sua presença sinaliza que o solo não foi arado ou degradado, servindo como referência para avaliação da qualidade ambiental dos campos sulinos."}',
  '[{"title":"Resistente ao fogo","description":"Como muitas gramíneas campestres, o capim-barba-de-bode é adaptado a queimadas periódicas — suas touceiras rebrotam rapidamente após o fogo, que elimina competidores."},{"title":"Nome pela aparência","description":"O nome popular vem das longas aristas (pelos) das sementes, que lembram a barba de um bode quando balançam ao vento."},{"title":"Biodiversidade oculta","description":"Os campos dominados por esta gramínea abrigam uma riqueza surpreendente: em um único metro quadrado de campo nativo podem ser encontradas até 40 espécies de plantas diferentes."}]'),

('algarrobo', 'pampa', 'flora', 'Algarrobo', 'Prosopis affinis', 'Árvore', 'Vulnerável', '🌳', null, null, null,
  'Árvore típica dos campos do extremo sul, produz vagens doces consumidas pelo gado e fauna silvestre.',
  '[{"label":"Altura","value":"5–10 m"},{"label":"Fruto","value":"Vagem doce"},{"label":"Habitat","value":"Campos e espinilhos"},{"label":"Distribuição","value":"Pampa gaúcho e Uruguai"}]',
  '{"title":"A árvore dos espinilhais ameaçados","description":"O algarrobo é espécie-chave dos espinilhais — formação vegetal exclusiva do Pampa e uma das mais ameaçadas do Brasil. Suas vagens doces alimentam fauna silvestre e gado, e suas raízes profundas fixam nitrogênio no solo, enriquecendo campos degradados."}',
  '[{"title":"Farinha de algarroba","description":"As vagens do algarrobo podem ser moídas para produzir uma farinha doce e nutritiva, consumida há séculos por povos indígenas e ainda utilizada como substituto do cacau."},{"title":"Ecossistema exclusivo","description":"Os espinilhais onde o algarrobo vive são encontrados apenas no extremo sul do Rio Grande do Sul e no Uruguai, sendo uma das formações vegetais mais raras e ameaçadas do Brasil."},{"title":"Fixa nitrogênio","description":"Como leguminosa, o algarrobo possui bactérias simbióticas nas raízes que capturam nitrogênio do ar e o fixam no solo, fertilizando naturalmente o terreno ao seu redor."}]'),

('pitanga', 'pampa', 'flora', 'Pitangueira', 'Eugenia uniflora', 'Árvore', 'Pouco preocupante', '🍒', null, null, null,
  'Árvore frutífera nativa, cujos frutos vermelhos são consumidos in natura e usados para geleias, sucos e licores.',
  '[{"label":"Altura","value":"4–10 m"},{"label":"Fruto","value":"Pitanga"},{"label":"Uso","value":"Alimentício"},{"label":"Distribuição","value":"Sul e Sudeste do Brasil"}]',
  '{"title":"Uma frutífera essencial para a fauna","description":"A pitangueira é uma das frutíferas nativas mais importantes para a fauna do Pampa, alimentando dezenas de espécies de aves, incluindo sabiás, sanhaços e bem-te-vis. Sua presença em áreas urbanas e rurais ajuda a manter a conectividade ecológica entre fragmentos de vegetação nativa."}',
  '[{"title":"Conhecida mundialmente","description":"A pitangueira foi levada para outros continentes pelos portugueses e hoje é cultivada na África, Ásia e Oceania, onde é conhecida como \"Brazilian cherry\" ou \"Surinam cherry\"."},{"title":"Repelente natural","description":"As folhas da pitangueira contêm óleos essenciais com propriedades repelentes contra insetos, sendo usadas popularmente para espantar moscas e mosquitos."},{"title":"Fruta em formato de abóbora","description":"A pitanga tem formato achatado com gomos que lembram uma mini abóbora. Muda de cor conforme amadurece: de verde para amarelo, laranja e finalmente vermelho-escuro."}]'),

('marcela', 'pampa', 'flora', 'Marcela', 'Achyrocline satureioides', 'Arbusto', 'Pouco preocupante', '🌼', null, null, null,
  'Planta aromática e medicinal, usada como chá digestivo e anti-inflamatório na medicina popular gaúcha.',
  '[{"label":"Altura","value":"30–50 cm"},{"label":"Uso","value":"Medicinal"},{"label":"Floração","value":"Mar–Abr"},{"label":"Distribuição","value":"Sul do Brasil e Uruguai"}]',
  '{"title":"A planta medicinal dos pampas","description":"A marcela é a planta medicinal mais utilizada na cultura gaúcha, com propriedades digestivas, anti-inflamatórias e calmantes comprovadas cientificamente. Sua colheita sustentável no campo gera renda para comunidades rurais e mantém a tradição da fitoterapia popular."}',
  '[{"title":"Colheita na Sexta-feira Santa","description":"Na tradição gaúcha, a marcela colhida na manhã da Sexta-feira Santa é considerada mais potente, reunindo famílias nos campos em um ritual que mistura religião e medicina popular."},{"title":"Travesseiro aromático","description":"No interior do Rio Grande do Sul, flores secas de marcela são usadas para rechear travesseiros, que ajudam a aliviar dores de cabeça e promover um sono tranquilo."},{"title":"Resistente e pioneira","description":"A marcela é uma das primeiras plantas a colonizar terrenos abandonados e beiras de estrada, preparando o solo para espécies mais exigentes — uma verdadeira pioneira ecológica."}]');

-- espécies — pantanal fauna
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('tuiuiu', 'pantanal', 'fauna', 'Tuiuiú', 'Jabiru mycteria', 'Ave', 'Pouco preocupante', '🦩', null, null, null,
  'Ave-símbolo do Pantanal, é uma das maiores aves do Brasil com envergadura de até 2,8 metros. Constrói enormes ninhos em árvores.',
  '[{"label":"Envergadura","value":"até 2,8 m"},{"label":"Dieta","value":"Peixes"},{"label":"Habitat","value":"Áreas alagadas"},{"label":"Distribuição","value":"Pantanal e América Latina"}]',
  '{"title":"O gigante guardião das águas","description":"O tuiuiú é um importante indicador da saúde dos ecossistemas alagados do Pantanal. Como predador de topo no ambiente aquático, controla populações de peixes e regula cadeias alimentares. Seus enormes ninhos são reutilizados por outras aves e servem de plataforma para observação."}',
  '[{"title":"Ninho gigante","description":"Os ninhos do tuiuiú podem medir até 2 metros de diâmetro e 1 metro de profundidade, pesando centenas de quilos. São reutilizados e ampliados a cada ano."},{"title":"Papo vermelho","description":"O tuiuiú possui um grande papo vermelho na base do pescoço que infla durante as interações sociais e no período de cortejo, sinalizando saúde e vigor."},{"title":"Pescoço termômetro","description":"A coloração do pescoço e do papo muda de intensidade conforme a temperatura corporal e o estado emocional da ave, ficando mais vermelho durante excitação."}]'),

('arara-azul', 'pantanal', 'fauna', 'Arara-azul', 'Anodorhynchus hyacinthinus', 'Ave', 'Vulnerável', '🦜', null, null, null,
  'A maior arara do mundo, com plumagem azul-cobalto vibrante. O Pantanal é seu principal refúgio, com cerca de 5.000 indivíduos.',
  '[{"label":"Tamanho","value":"até 1 m"},{"label":"Dieta","value":"Frugívoro"},{"label":"Habitat","value":"Palmeirais"},{"label":"Distribuição","value":"Pantanal e Cerrado"}]',
  '{"title":"A jardineira azul do Pantanal","description":"A arara-azul é essencial para a dispersão de sementes de palmeiras no Pantanal, especialmente do acuri e da bocaiuva. Ao quebrar os cocos com seu bico poderoso, ela disponibiliza alimento para outras espécies menores e promove a regeneração dos palmeirais."}',
  '[{"title":"Bico quebra-nozes","description":"O bico da arara-azul exerce uma pressão de mais de 70 kg/cm², capaz de quebrar cocos de palmeiras que nenhuma outra ave consegue abrir."},{"title":"Casal fiel","description":"As araras-azuis formam casais que permanecem juntos por toda a vida, voando sempre lado a lado e compartilhando o cuidado com os filhotes."},{"title":"Salva por uma bióloga","description":"A bióloga Neiva Guedes dedicou mais de 30 anos à conservação da arara-azul no Pantanal. Graças ao seu trabalho, a população cresceu de 1.500 para mais de 5.000 indivíduos."}]'),

('jacare-do-pantanal', 'pantanal', 'fauna', 'Jacaré-do-pantanal', 'Caiman yacare', 'Réptil', 'Pouco preocupante', '🐊', null, null, null,
  'O crocodiliano mais abundante do Pantanal, com população estimada em milhões. É essencial para o controle de peixes piranha.',
  '[{"label":"Tamanho","value":"até 2,5 m"},{"label":"Dieta","value":"Carnívoro"},{"label":"Habitat","value":"Rios e lagoas"},{"label":"Distribuição","value":"Pantanal e bacia do Paraguai"}]',
  '{"title":"O regulador dos ecossistemas aquáticos","description":"O jacaré-do-pantanal é fundamental para o equilíbrio dos rios e lagoas, controlando populações de piranhas e outros peixes. Durante a seca, quando se concentram em poças, seus excrementos fertilizam a água e sustentam toda a cadeia alimentar aquática."}',
  '[{"title":"Milhões de indivíduos","description":"Estima-se que existam cerca de 10 milhões de jacarés no Pantanal, tornando-o a maior concentração de crocodilianos do mundo."},{"title":"Temperatura define o sexo","description":"O sexo dos filhotes é determinado pela temperatura do ninho durante a incubação: temperaturas mais altas produzem machos, e mais baixas, fêmeas."},{"title":"Quase caçado até a extinção","description":"Nas décadas de 1970 e 80, milhões de jacarés eram abatidos anualmente no Pantanal para o comércio de couro. A proibição da caça em 1967 permitiu a recuperação da população."}]'),

('capivara', 'pantanal', 'fauna', 'Capivara', 'Hydrochoerus hydrochaeris', 'Mamífero', 'Pouco preocupante', '🐹', null, null, null,
  'O maior roedor do mundo, altamente social e semiaquático. É extremamente comum no Pantanal, vivendo em grupos de até 20 indivíduos.',
  '[{"label":"Peso","value":"até 80 kg"},{"label":"Dieta","value":"Herbívoro"},{"label":"Habitat","value":"Margens de rios"},{"label":"Distribuição","value":"América do Sul"}]',
  '{"title":"A engenheira das margens dos rios","description":"A capivara desempenha um papel ecológico importante ao manter a vegetação das margens de rios e lagos aparada, prevenindo o crescimento excessivo de plantas aquáticas. Também serve como presa para onças, jacarés e sucuris, sendo fundamental na cadeia alimentar do Pantanal."}',
  '[{"title":"Maior roedor do mundo","description":"Com até 80 kg, a capivara é o maior roedor vivo do planeta. Seus ancestrais pré-históricos eram ainda maiores — do tamanho de um urso."},{"title":"Peixe na Quaresma","description":"No século XVIII, a Igreja Católica classificou a capivara como \"peixe\" para fins de jejum quaresmal, por ser semiaquática. A tradição de consumi-la na Quaresma persiste em algumas regiões."},{"title":"Vida social intensa","description":"As capivaras vivem em grupos hierarquizados de até 20 indivíduos, com um macho dominante. São altamente sociais e frequentemente vistas junto a aves que removem parasitas de sua pele."}]');

-- espécies — pantanal flora
insert into species (id, biome, type, name, scientific, category, status, emoji, image, hero_image, detail_image, description, traits, importance, fun_facts) values
('piuva', 'pantanal', 'flora', 'Piúva', 'Handroanthus impetiginosus', 'Árvore', 'Pouco preocupante', '🌸', null, null, null,
  'Ipê-rosa do Pantanal que transforma a paisagem com floração exuberante entre julho e setembro.',
  '[{"label":"Altura","value":"10–20 m"},{"label":"Floração","value":"Jul–Set"},{"label":"Uso","value":"Ornamental"},{"label":"Distribuição","value":"Pantanal e Cerrado"}]',
  '{"title":"A pintora de paisagens do Pantanal","description":"A piúva transforma a paisagem do Pantanal com suas flores rosadas durante a estação seca, fornecendo néctar essencial para beija-flores e abelhas em um período de escassez. Sua floração sincronizada atrai turistas e movimenta a economia local."}',
  '[{"title":"Espetáculo anual","description":"Entre julho e setembro, campos inteiros do Pantanal se cobrem de rosa com a floração das piúvas, criando um espetáculo que rivaliza com a floração das cerejeiras no Japão."},{"title":"Floresce sem folhas","description":"A piúva perde todas as folhas antes de florescer, concentrando toda a energia na produção de flores. O contraste das flores rosas contra os galhos secos é visualmente impactante."},{"title":"Madeira resistente à água","description":"A madeira da piúva é naturalmente resistente à umidade e aos fungos, sendo utilizada em construções rurais do Pantanal que ficam parcialmente submersas durante as cheias."}]'),

('camalote', 'pantanal', 'flora', 'Camalote', 'Eichhornia crassipes', 'Aquática', 'Pouco preocupante', '💧', null, null, null,
  'Planta aquática flutuante que forma extensos tapetes verdes sobre a água. Importante abrigo para peixes jovens.',
  '[{"label":"Habitat","value":"Águas calmas"},{"label":"Flor","value":"Lilás"},{"label":"Tipo","value":"Flutuante"},{"label":"Distribuição","value":"Pantanal e bacias brasileiras"}]',
  '{"title":"O berçário flutuante do Pantanal","description":"Os tapetes de camalote funcionam como berçários naturais para peixes jovens, que se escondem entre as raízes submersas de predadores maiores. Também absorvem nutrientes em excesso da água, atuando como filtro biológico natural nos rios e lagoas."}',
  '[{"title":"Crescimento explosivo","description":"O camalote pode dobrar sua biomassa em apenas duas semanas, sendo uma das plantas de crescimento mais rápido do mundo. Sem controle natural, pode cobrir lagos inteiros."},{"title":"Invasora mundial","description":"Levada como planta ornamental para outros continentes, a Eichhornia crassipes se tornou uma das espécies invasoras mais destrutivas do planeta, obstruindo rios e reservatórios na África e Ásia."},{"title":"Flor de um dia","description":"Cada flor lilás do camalote dura apenas um dia. Após a polinização, a haste floral se curva para baixo, submergindo o fruto na água para liberar as sementes."}]'),

('acuri', 'pantanal', 'flora', 'Acuri', 'Attalea phalerata', 'Palmeira', 'Pouco preocupante', '🌴', null, null, null,
  'Palmeira abundante no Pantanal, seus frutos são alimento essencial para araras-azuis, que dependem dela para sobreviver.',
  '[{"label":"Altura","value":"10–15 m"},{"label":"Fruto","value":"Coco-de-acuri"},{"label":"Relação","value":"Arara-azul"},{"label":"Distribuição","value":"Pantanal e Cerrado"}]',
  '{"title":"A palmeira que sustenta a arara-azul","description":"O acuri é a principal fonte de alimento da arara-azul no Pantanal, formando uma relação de dependência ecológica fundamental. Sem os extensos acurizais, a sobrevivência da arara-azul estaria ameaçada. Seus frutos também alimentam antas, porcos-do-mato e dezenas de outras espécies."}',
  '[{"title":"Coco blindado","description":"O coco-de-acuri possui uma casca tão dura que praticamente apenas a arara-azul, com sua mandíbula poderosíssima, consegue quebrá-lo. Após a arara, roedores aproveitam os pedaços."},{"title":"Palmeira resistente ao fogo","description":"O acuri é altamente resistente a queimadas, com a base do tronco protegida por bainhas foliares densas. Após o fogo, é uma das primeiras palmeiras a se recuperar."},{"title":"Sombra para o gado","description":"Os acurizais são os pontos preferidos de descanso do gado pantaneiro durante o calor do dia, criando um sistema silvipastoril natural que existe há séculos."}]'),

('cambara', 'pantanal', 'flora', 'Cambará', 'Vochysia divergens', 'Árvore', 'Pouco preocupante', '🌳', null, null, null,
  'Árvore invasora nativa que se expande nas áreas de campo do Pantanal. Sua presença indica mudanças no regime de inundação.',
  '[{"label":"Altura","value":"7–18 m"},{"label":"Flor","value":"Amarela"},{"label":"Habitat","value":"Campos inundáveis"},{"label":"Distribuição","value":"Pantanal"}]',
  '{"title":"A árvore que transforma paisagens","description":"O cambará é uma espécie pioneira que coloniza campos abertos alagáveis do Pantanal, transformando-os gradualmente em áreas florestadas (cambarazais). Esse processo natural de sucessão ecológica cria novos habitats para espécies florestais, mas preocupa pecuaristas pela perda de pastagens."}',
  '[{"title":"Invasora nativa","description":"O cambará é nativo do Pantanal, mas se comporta como invasora, expandindo-se agressivamente sobre campos nativos. O aumento das cheias e mudanças no uso do solo aceleram sua expansão."},{"title":"Raízes aéreas","description":"Para sobreviver em áreas alagadas durante meses, o cambará desenvolve raízes aéreas e lenticelas no tronco que permitem a troca de gases mesmo com a base submersa."},{"title":"Mel de cambará","description":"O mel produzido a partir das flores de cambará é muito valorizado no Pantanal por seu sabor suave e aroma floral característico, sendo um produto tradicional da região."}]');

-- ecossistemas — amazônia
insert into ecosystems (id, biome, name, category, emoji, image, hero_image, detail_image, description, subtitle, traits, about, importance, fun_facts) values
('terra-firme', 'amazonia', 'Terra firme', 'Terra firme', '🌳', '/images/ecosystems/terra-firme.png', '/images/ecosystems/terra-firme-hero.png', '/images/ecosystems/terra-firme-detail.png',
  'Áreas que não sofrem alagamentos periódicos, com grande diversidade de árvores e animais.',
  'Floresta não alagável',
  '[{"label":"Alagamento","value":"Não sofre alagamentos periódicos"},{"label":"Vegetação","value":"Floresta densa e diversa"},{"label":"Solo","value":"Áreas mais elevadas"},{"label":"Bioma","value":"Amazônia"}]',
  'As florestas de terra firme estão localizadas em áreas mais elevadas da Amazônia, onde o solo não é coberto pelas águas dos rios durante os períodos de cheia. Esses ambientes apresentam árvores de grande porte e uma enorme diversidade de plantas e animais. É o tipo de floresta mais extenso da Amazônia, cobrindo cerca de 80% do bioma.',
  '{"title":"Um ambiente essencial para a biodiversidade","description":"A terra firme abriga uma grande variedade de espécies e oferece diferentes habitats, recursos e condições para a manutenção da biodiversidade amazônica. Sua extensão contínua permite o deslocamento de grandes mamíferos e a dispersão de sementes a longas distâncias."}',
  '[{"title":"Não é uma floresta alagada","description":"Diferente das várzeas e dos igapós, a terra firme não sofre inundação periódica pelos rios."},{"title":"Abriga árvores gigantes","description":"Muitas árvores de grande porte podem crescer nesses ambientes, formando um dossel fechado que ultrapassa 40 metros de altura."},{"title":"Grande diversidade de vida","description":"A variedade de plantas cria diferentes habitats para animais, fungos e outros organismos em cada estrato da floresta."}]'),

('rios-amazonicos', 'amazonia', 'Rios amazônicos', 'Rios', '🏞️', '/images/ecosystems/rios-amazonicos.png', null, null,
  'Uma extensa rede de rios que conecta diferentes ambientes e sustenta inúmeras formas de vida.',
  'A maior rede fluvial do mundo',
  '[{"label":"Tipo","value":"Rede fluvial de grande escala"},{"label":"Vegetação","value":"Matas ciliares e aquáticas"},{"label":"Ciclo","value":"Cheia (dez–jun) e seca (jul–nov)"},{"label":"Importância","value":"Transporte e sustento de comunidades"}]',
  'A bacia amazônica contém cerca de 20% da água doce superficial do planeta, formando uma rede de rios com milhares de quilômetros de extensão. Seus rios são classificados por cor — de águas brancas, negras ou claras — cada tipo com características químicas e ecológicas distintas. Essa rede conecta florestas de terra firme, várzeas e igapós.',
  '{"title":"As artérias da maior floresta do mundo","description":"Os rios amazônicos transportam nutrientes, sementes e sedimentos que fertilizam milhões de hectares de floresta. São as vias de conexão entre ecossistemas e comunidades ribeirinhas que dependem da água para sobreviver."}',
  '[{"title":"Cores diferentes","description":"Os rios amazônicos têm três cores distintas: branca (rico em sedimentos), negra (rico em ácidos orgânicos) e clara (baixa quantidade de sedimentos)."},{"title":"Volume impressionante","description":"O rio Amazonas despeja no oceano cerca de 200 mil metros cúbicos de água por segundo, o maior volume do mundo."},{"title":"Encontro das águas","description":"O encontro do rio Negro com o Solimões cria um fenômeno visual onde as águas escuras e claras correm lado a lado sem se misturar por quilômetros."}]'),

('varzeas', 'amazonia', 'Várzeas', 'Várzeas', '💧', '/images/ecosystems/varzeas.png', null, null,
  'Áreas periodicamente inundadas pelos rios, formando ambientes ricos em nutrientes.',
  'Planície fértil de inundação',
  '[{"label":"Tipo","value":"Floresta de planície inundável"},{"label":"Vegetação","value":"Árvores adaptadas à submersão"},{"label":"Solo","value":"Rico em sedimentos e nutrientes"},{"label":"Ciclo","value":"Inundação sazonal (4–7 meses)"}]',
  'As várzeas são florestas de planície inundável associadas a rios de águas brancas, ricas em sedimentos andinos. Durante a cheia, a água pode subir até 12 metros, submergindo parcialmente as árvores. Quando as águas baixam, o solo fica recoberto de nutrientes, tornando as várzeas um dos ambientes mais produtivos da Amazônia.',
  '{"title":"O celeiro natural da Amazônia","description":"As várzeas são essenciais para a reprodução de centenas de espécies de peixes, que entram na floresta alagada para se alimentar e desovar. Também sustentam a agricultura de subsistência de comunidades ribeirinhas com seus solos férteis."}',
  '[{"title":"Florestas submersas","description":"Durante a cheia, peixes nadam entre as copas das árvores parcialmente submersas, alimentando-se de frutos e sementes."},{"title":"Solo renovável","description":"A cada ciclo de cheia, novos sedimentos ricos em nutrientes são depositados, renovando a fertilidade do solo naturalmente."},{"title":"Berçário de peixes","description":"Mais de 200 espécies de peixes dependem das várzeas para reprodução, incluindo espécies de grande importância econômica como o tambaqui."}]'),

('igapos', 'amazonia', 'Igapós', 'Igapós', '🌊', '/images/ecosystems/igapos.png', null, null,
  'Florestas que permanecem alagadas por longos períodos, adaptadas às águas escuras dos rios.',
  'Floresta de águas negras',
  '[{"label":"Tipo","value":"Floresta permanentemente alagada"},{"label":"Vegetação","value":"Árvores com raízes aéreas"},{"label":"Solo","value":"Arenoso e pobre em nutrientes"},{"label":"Ciclo","value":"Alagamento prolongado (até 10 meses)"}]',
  'Os igapós são florestas permanentemente ou semipermanentemente alagadas, associadas a rios de águas negras ou claras. Diferente das várzeas, os solos dos igapós são pobres em nutrientes. As árvores desenvolveram adaptações extremas, como raízes aéreas e troncos que resistem a meses submersos. A água escura deve sua cor à decomposição de matéria orgânica vegetal.',
  '{"title":"Um ecossistema de resistência","description":"Os igapós demonstram a capacidade de adaptação da vida a condições extremas. Suas árvores fixam carbono mesmo parcialmente submersas e fornecem abrigo e alimento para peixes, botos e diversas espécies aquáticas durante os longos períodos de cheia."}',
  '[{"title":"Águas cor de chá","description":"A coloração escura da água vem dos taninos liberados pela decomposição de folhas e troncos, criando um ambiente ácido e pobre em nutrientes."},{"title":"Árvores submarinas","description":"Algumas espécies de árvores podem passar até 10 meses com seus troncos parcialmente submersos, sem morrer."},{"title":"Peixes frugívoros","description":"Muitos peixes dos igapós se alimentam exclusivamente de frutos e sementes que caem das árvores na água."}]');

-- ecossistemas — cerrado
insert into ecosystems (id, biome, name, category, emoji, image, hero_image, detail_image, description, subtitle, traits, about, importance, fun_facts) values
('cerradao', 'cerrado', 'Cerradão', 'Cerradão', '🌲', null, null, null,
  'Formação florestal densa do Cerrado, com dossel fechado e árvores de até 15 metros.',
  'Floresta densa do Cerrado',
  '[{"label":"Tipo","value":"Formação florestal com dossel fechado"},{"label":"Vegetação","value":"Árvores de 12 a 15 metros"},{"label":"Solo","value":"Mais fértil que o cerrado típico"},{"label":"Importância","value":"Estoque de carbono e biodiversidade"}]',
  'O cerradão é a formação florestal mais densa do Cerrado, com dossel que pode atingir 70% de cobertura. Suas árvores são mais altas e retilíneas do que nas formações savânicas, com troncos menos tortuosos. Ocorre geralmente em solos mais férteis ou profundos e compartilha espécies tanto com o cerrado típico quanto com florestas estacionais vizinhas.',
  '{"title":"A floresta escondida do Cerrado","description":"O cerradão é um importante estoque de carbono dentro do bioma e funciona como corredor ecológico entre fragmentos florestais. Sua estrutura mais fechada oferece abrigo para espécies que não sobrevivem nas formações abertas do Cerrado."}',
  '[{"title":"Cerrado com cara de floresta","description":"Apesar de estar no bioma Cerrado, o cerradão lembra uma floresta tropical, com dossel fechado e sombra no interior."},{"title":"Solo mais fértil","description":"Diferente do cerrado típico, o cerradão ocorre sobre solos com maior teor de nutrientes, o que permite o crescimento de árvores maiores."},{"title":"Espécies de dois mundos","description":"O cerradão abriga tanto espécies típicas do Cerrado quanto da Mata Atlântica e de florestas estacionais."}]'),

('campo-limpo', 'cerrado', 'Campo limpo', 'Campo limpo', '🌾', null, null, null,
  'Vegetação predominantemente herbácea, sem árvores, dominada por gramíneas nativas.',
  'Campos abertos de gramíneas',
  '[{"label":"Tipo","value":"Formação campestre sem árvores"},{"label":"Vegetação","value":"Gramíneas e herbáceas"},{"label":"Solo","value":"Raso, ácido e com pouca matéria orgânica"},{"label":"Importância","value":"Recarga hídrica e endemismo"}]',
  'O campo limpo é a formação mais aberta do Cerrado, composta quase exclusivamente por gramíneas e pequenas plantas herbáceas. Não possui árvores ou arbustos significativos. Ocorre geralmente em topos de morros, encostas e áreas com solo raso ou encharcado. Apesar da aparência simples, abriga enorme diversidade de espécies rasteiras, muitas delas endêmicas.',
  '{"title":"Um tapete vivo de diversidade","description":"Os campos limpos são essenciais para a recarga de aquíferos, pois a ausência de árvores facilita a infiltração de água da chuva no solo. Abrigam centenas de espécies de gramíneas e herbáceas encontradas exclusivamente nesse tipo de ambiente."}',
  '[{"title":"Mais diverso do que parece","description":"Um metro quadrado de campo limpo pode conter mais de 30 espécies diferentes de plantas, superando muitas florestas."},{"title":"Fogo que renova","description":"As gramíneas do campo limpo são adaptadas ao fogo natural e rebrotam rapidamente após as queimadas do Cerrado."},{"title":"Esponjas naturais","description":"Os campos limpos sobre solos profundos funcionam como esponjas, absorvendo água da chuva e alimentando nascentes e rios."}]'),

('veredas', 'cerrado', 'Veredas', 'Veredas', '🌴', null, null, null,
  'Áreas úmidas com palmeiras buriti, fundamentais para nascentes e cursos d''água.',
  'Área úmida com palmeiras',
  '[{"label":"Tipo","value":"Área úmida com palmeiras"},{"label":"Vegetação","value":"Dominada pelo buriti"},{"label":"Solo","value":"Encharcado, rico em matéria orgânica"},{"label":"Importância","value":"Regulação hídrica e corredores ecológicos"}]',
  'As veredas se formam em áreas de nascentes onde o solo permanece encharcado. A palmeira buriti domina a paisagem e pode atingir 30 metros. Funcionam como corredores ecológicos e são vitais para a fauna e o abastecimento de água. São consideradas patrimônio ecológico do Cerrado e protegidas por lei.',
  '{"title":"Um ambiente essencial para a água","description":"As veredas são responsáveis por proteger nascentes que alimentam grandes rios brasileiros. Sua destruição compromete o abastecimento de água de regiões inteiras e elimina corredores que conectam diferentes áreas do Cerrado."}',
  '[{"title":"Grande Sertão","description":"As veredas são tão marcantes que deram nome ao maior romance brasileiro: Grande Sertão: Veredas, de Guimarães Rosa."},{"title":"Árvore da vida","description":"Do buriti se extrai polpa para doces, óleo, fibras para artesanato e madeira. Nada se desperdiça."},{"title":"Refúgio da fauna","description":"Araras, lobos-guarás e veados-campeiros dependem das veredas para beber água na estação seca."}]'),

('matas-galeria', 'cerrado', 'Matas de galeria', 'Matas de galeria', '🌿', null, null, null,
  'Florestas que margeiam os rios no Cerrado, formando corredores ecológicos.',
  'Florestas ao longo dos rios',
  '[{"label":"Tipo","value":"Floresta ciliar com dossel fechado"},{"label":"Vegetação","value":"Árvores de 20 a 30 metros"},{"label":"Solo","value":"Úmido e rico em nutrientes"},{"label":"Importância","value":"Proteção de cursos d''água"}]',
  'As matas de galeria são florestas que acompanham os cursos d''água no Cerrado, formando faixas verdes e densas em contraste com a vegetação aberta ao redor. Suas copas se encontram sobre os rios, criando um túnel de vegetação. Abrigam espécies de floresta tropical em pleno Cerrado e funcionam como corredores que conectam biomas distantes.',
  '{"title":"Os corredores verdes do Cerrado","description":"As matas de galeria protegem as margens dos rios contra erosão e assoreamento, mantendo a qualidade da água. Funcionam como pontes biológicas, permitindo que espécies de floresta se desloquem através da paisagem aberta do Cerrado."}',
  '[{"title":"Túnel de verde","description":"As copas das árvores de cada margem se encontram sobre o rio, formando um corredor sombreado que mantém a temperatura da água estável."},{"title":"Floresta dentro da savana","description":"Muitas espécies típicas da Mata Atlântica e da Amazônia são encontradas nessas matas, mesmo estando no coração do Cerrado."},{"title":"Filtro natural","description":"A vegetação das matas de galeria filtra poluentes e sedimentos antes que cheguem aos rios, funcionando como estação de tratamento natural."}]');

-- ecossistemas — mata atlântica
insert into ecosystems (id, biome, name, category, emoji, image, hero_image, detail_image, description, subtitle, traits, about, importance, fun_facts) values
('floresta-ombrofila', 'mata-atlantica', 'Floresta ombrófila', 'Floresta ombrófila', '🌳', null, null, null,
  'Floresta densa e úmida que recebe chuvas abundantes o ano todo, com alta biodiversidade.',
  'Floresta densa e úmida',
  '[{"label":"Tipo","value":"Floresta tropical perenifólia"},{"label":"Vegetação","value":"Dossel com 25 a 35 metros"},{"label":"Solo","value":"Profundo, úmido e rico em húmus"},{"label":"Importância","value":"Centro de endemismo e biodiversidade"}]',
  'A floresta ombrófila densa é a formação mais exuberante da Mata Atlântica, caracterizada por chuvas abundantes distribuídas ao longo do ano. Apresenta múltiplos estratos de vegetação, com árvores emergentes que ultrapassam 35 metros, epífitas, bromélias e orquídeas. É um dos ecossistemas com maior biodiversidade por hectare do planeta.',
  '{"title":"O coração verde da Mata Atlântica","description":"A floresta ombrófila concentra a maior parte da biodiversidade da Mata Atlântica, incluindo milhares de espécies endêmicas que não existem em nenhum outro lugar do mundo. Sua conservação é essencial para a regulação do clima e o abastecimento de água de grandes centros urbanos."}',
  '[{"title":"Jardim vertical","description":"Uma única árvore da floresta ombrófila pode abrigar centenas de bromélias, orquídeas, musgos e samambaias em seus troncos e galhos."},{"title":"Chuva o ano todo","description":"O nome \"ombrófila\" vem do grego e significa \"amiga da chuva\" — essa floresta recebe precipitação em todos os meses do ano."},{"title":"Restam apenas 12%","description":"Da cobertura original da Mata Atlântica, restam entre 12% e 16%, e a floresta ombrófila é uma das formações mais ameaçadas."}]'),

('restinga', 'mata-atlantica', 'Restinga', 'Restinga', '🏖️', null, null, null,
  'Vegetação sobre solos arenosos do litoral, com plantas adaptadas à salinidade e ventos.',
  'Vegetação costeira sobre areia',
  '[{"label":"Tipo","value":"Vegetação litorânea sobre dunas"},{"label":"Vegetação","value":"Herbácea a arbórea, adaptada"},{"label":"Solo","value":"Arenoso, salino e pobre"},{"label":"Importância","value":"Fixação de dunas e proteção costeira"}]',
  'A restinga é um ecossistema costeiro que se desenvolve sobre depósitos arenosos ao longo do litoral. Sua vegetação varia de rasteira próxima ao mar até arbórea no interior, formando um gradiente de adaptação à salinidade, ventos e pobreza do solo. É habitat de espécies endêmicas e ponto de nidificação para aves marinhas e tartarugas.',
  '{"title":"A guardiã da costa brasileira","description":"A restinga protege a costa contra a erosão marinha, fixa dunas que poderiam avançar sobre áreas habitadas e funciona como zona de transição entre o mar e a floresta. Sua vegetação é fundamental para a estabilidade de praias e lagunas costeiras."}',
  '[{"title":"Plantas esculpidas pelo vento","description":"A vegetação mais próxima ao mar é moldada pelos ventos constantes, crescendo rente ao solo em formas arredondadas."},{"title":"Berçário de tartarugas","description":"As praias de restinga são locais de desova de tartarugas marinhas que retornam ao mesmo trecho de areia todos os anos."},{"title":"Orquídeas na areia","description":"Apesar do solo pobre, a restinga abriga dezenas de espécies de orquídeas adaptadas a crescer em condições extremas."}]'),

('manguezal', 'mata-atlantica', 'Manguezal', 'Manguezal', '🦀', null, null, null,
  'Ecossistema costeiro de transição entre rios e mar, berçário de diversas espécies marinhas.',
  'Berçário entre o rio e o mar',
  '[{"label":"Tipo","value":"Ecossistema costeiro de transição"},{"label":"Vegetação","value":"Mangue com raízes aéreas"},{"label":"Solo","value":"Lodoso, salino e anaeróbico"},{"label":"Importância","value":"Berçário de espécies marinhas"}]',
  'O manguezal é um ecossistema costeiro que ocorre na zona de encontro entre rios e mar, em áreas protegidas como estuários e baías. Suas árvores possuem raízes aéreas que permitem respirar no solo alagado e pobre em oxigênio. É considerado um dos ecossistemas mais produtivos do planeta, servindo como berçário para até 75% das espécies de peixes comerciais do litoral.',
  '{"title":"O berçário do oceano","description":"Os manguezais são essenciais para a manutenção dos estoques pesqueiros, pois a maioria dos peixes, camarões e caranguejos comerciais passa parte do ciclo de vida entre suas raízes. Também funcionam como barreira natural contra ressacas, marés e tsunamis."}',
  '[{"title":"Raízes que respiram","description":"As raízes aéreas do mangue-vermelho captam oxigênio diretamente do ar, pois o solo lodoso é quase sem oxigênio."},{"title":"Superpoder contra o carbono","description":"Os manguezais armazenam até 5 vezes mais carbono por hectare do que florestas tropicais terrestres."},{"title":"Fábrica de caranguejos","description":"Um único hectare de manguezal pode sustentar mais de 2 milhões de caranguejos, base alimentar de comunidades costeiras."}]'),

('campos-altitude', 'mata-atlantica', 'Campos de altitude', 'Campos de altitude', '⛰️', null, null, null,
  'Vegetação herbácea e arbustiva no topo de montanhas, com espécies endêmicas adaptadas ao frio.',
  'Vegetação de topo de montanha',
  '[{"label":"Tipo","value":"Formação campestre de altitude"},{"label":"Vegetação","value":"Herbácea e arbustiva baixa"},{"label":"Solo","value":"Rochoso, raso e ácido"},{"label":"Importância","value":"Alto endemismo e nascentes"}]',
  'Os campos de altitude ocorrem acima de 1.500 metros nas serras da Mata Atlântica, onde as temperaturas são mais baixas e os ventos mais fortes. A vegetação é rasteira e resistente, composta por gramíneas, liquens e arbustos adaptados ao frio, geada e solos rasos sobre rochas. São verdadeiras ilhas de biodiversidade isoladas nos topos das montanhas.',
  '{"title":"Ilhas de vida nas alturas","description":"Os campos de altitude são centros de endemismo, pois o isolamento geográfico nos topos de montanhas fez com que espécies evoluíssem independentemente. São também áreas de recarga hídrica, onde nascem rios que abastecem milhões de pessoas nas cidades abaixo."}',
  '[{"title":"Geada tropical","description":"Apesar de estarem em região tropical, os campos de altitude registram temperaturas abaixo de zero e geadas frequentes no inverno."},{"title":"Espécies únicas","description":"Muitas plantas dos campos de altitude existem apenas em um único pico de montanha e em nenhum outro lugar do planeta."},{"title":"Nascentes nas nuvens","description":"A umidade das nuvens que toca os cumes alimenta nascentes que formam importantes rios da região sudeste."}]');

-- ecossistemas — caatinga
insert into ecosystems (id, biome, name, category, emoji, image, hero_image, detail_image, description, subtitle, traits, about, importance, fun_facts) values
('caatinga-arborea', 'caatinga', 'Caatinga arbórea', 'Caatinga arbórea', '🌵', null, null, null,
  'Formação mais alta da Caatinga, com árvores de até 15 metros que perdem folhas na seca.',
  'Floresta seca de porte alto',
  '[{"label":"Tipo","value":"Floresta tropical seca caducifólia"},{"label":"Vegetação","value":"Árvores de 7 a 15 metros"},{"label":"Solo","value":"Profundo e relativamente fértil"},{"label":"Importância","value":"Habitat de espécies ameaçadas"}]',
  'A caatinga arbórea é a formação mais alta e densa do bioma, com árvores que podem atingir 15 metros. Ocorre em áreas com solos mais profundos e maior disponibilidade de água. Durante a estação seca, as árvores perdem completamente suas folhas para economizar água, transformando a paisagem verde em um cenário acinzentado e aparentemente sem vida.',
  '{"title":"O refúgio de vida no semiárido","description":"A caatinga arbórea oferece sombra, abrigo e alimento para a fauna durante os períodos mais secos. É o habitat preferido de espécies ameaçadas como a ararinha-azul e funciona como reserva de umidade em uma região onde a água é escassa."}',
  '[{"title":"Floresta que desaparece","description":"Na seca, a caatinga arbórea perde todas as folhas e parece morta, mas volta a verdejar em poucos dias após as primeiras chuvas."},{"title":"Madeiras nobres","description":"Espécies como aroeira, braúna e umburana produzem madeiras de alta qualidade e resistência, valorizadas na marcenaria."},{"title":"Casa da ararinha-azul","description":"A caatinga arbórea do norte da Bahia era o único habitat natural da ararinha-azul, hoje em programa de reintrodução."}]'),

('carrasco', 'caatinga', 'Carrasco', 'Carrasco', '🏜️', null, null, null,
  'Vegetação arbustiva densa sobre solos arenosos, com espécies de porte baixo e folhas pequenas.',
  'Vegetação densa sobre areia',
  '[{"label":"Tipo","value":"Formação arbustiva densa"},{"label":"Vegetação","value":"Arbustos de 3 a 5 metros"},{"label":"Solo","value":"Arenoso profundo e pobre"},{"label":"Importância","value":"Endemismo e fixação de solo"}]',
  'O carrasco é uma formação vegetal densa e emaranhada que cresce sobre solos arenosos profundos nas chapadas da Caatinga. Suas plantas possuem folhas pequenas e duras, adaptadas à escassez de água e à pobreza do solo. Apesar da dificuldade de penetrar nessa vegetação compacta, o carrasco abriga espécies endêmicas que não ocorrem em nenhum outro tipo de vegetação.',
  '{"title":"Uma fortaleza verde sobre a areia","description":"O carrasco protege os solos arenosos contra a erosão eólica e hídrica, fixando dunas e chapadas. Sua vegetação densa funciona como refúgio para espécies exclusivas que evoluíram isoladas nas chapadas do Nordeste."}',
  '[{"title":"Impenetrável","description":"A vegetação é tão densa e emaranhada que é praticamente impossível caminhar através dela sem abrir caminho."},{"title":"Plantas exclusivas","description":"Várias espécies de plantas do carrasco não existem em nenhum outro ecossistema do mundo."},{"title":"Sobre dunas antigas","description":"Os solos arenosos do carrasco são resquícios de antigos sistemas de dunas formados há milhões de anos."}]'),

('campos-rupestres', 'caatinga', 'Campos rupestres', 'Campos rupestres', '🪨', null, null, null,
  'Vegetação sobre afloramentos rochosos com alto endemismo e espécies adaptadas à pouca água.',
  'Vegetação sobre rochas',
  '[{"label":"Tipo","value":"Formação sobre afloramentos rochosos"},{"label":"Vegetação","value":"Herbácea e arbustiva especializada"},{"label":"Solo","value":"Rochoso com pouco substrato"},{"label":"Importância","value":"Altíssimo endemismo de espécies"}]',
  'Os campos rupestres ocorrem sobre afloramentos de rochas quartzíticas ou areníticas, geralmente em altitudes acima de 900 metros. As plantas crescem nas fendas das rochas com mínimo substrato, desenvolvendo adaptações extremas à seca, ao vento e à intensa radiação solar. São verdadeiros hotspots de endemismo, com proporções comparáveis às ilhas oceânicas.',
  '{"title":"Jardins de pedra com vida única","description":"Os campos rupestres concentram uma das maiores taxas de endemismo de plantas do planeta. Muitas espécies medicinais e ornamentais, como as sempre-vivas, são exclusivas dessas formações. A destruição de um único afloramento pode significar a extinção de espécies inteiras."}',
  '[{"title":"Plantas em miniatura","description":"Muitas espécies desenvolveram formas anãs e suculentas para sobreviver com pouquíssima água e solo entre as rochas."},{"title":"Sempre-vivas","description":"As famosas flores sempre-vivas, usadas em artesanato e decoração, são nativas dos campos rupestres e estão ameaçadas pela coleta predatória."},{"title":"Ilhas terrestres","description":"Cada afloramento rochoso funciona como uma ilha isolada, fazendo com que espécies evoluam separadamente em picos vizinhos."}]'),

('brejos-altitude', 'caatinga', 'Brejos de altitude', 'Brejos de altitude', '🌧️', null, null, null,
  'Ilhas de mata úmida em serras elevadas dentro da Caatinga, refúgios de biodiversidade.',
  'Ilhas de mata úmida no sertão',
  '[{"label":"Tipo","value":"Enclave de floresta úmida"},{"label":"Vegetação","value":"Floresta densa e perenifólia"},{"label":"Solo","value":"Úmido e fértil nas encostas"},{"label":"Importância","value":"Refúgio de biodiversidade"}]',
  'Os brejos de altitude são enclaves de floresta úmida que ocorrem em serras e chapadas elevadas no interior do Nordeste. A altitude intercepta a umidade dos ventos, criando ilhas de vegetação exuberante cercadas pela caatinga seca. São refúgios de espécies de Mata Atlântica isoladas há milhares de anos, funcionando como cápsulas do tempo ecológicas.',
  '{"title":"Oásis de floresta no sertão","description":"Os brejos de altitude são relictos de uma floresta que cobria grande parte do Nordeste em períodos mais úmidos. Abrigam espécies de Mata Atlântica que ficaram isoladas e evoluíram separadamente, criando populações únicas. São essenciais para o abastecimento de água das comunidades serranas."}',
  '[{"title":"Mata Atlântica no sertão","description":"No meio da Caatinga seca, é possível encontrar samambaias, bromélias e orquídeas típicas de floresta úmida nos brejos de altitude."},{"title":"Cápsulas do tempo","description":"Essas matas ficaram isoladas há mais de 10 mil anos, quando o clima ficou mais seco, preservando espécies de épocas passadas."},{"title":"Fontes de água","description":"Os brejos captam a umidade dos ventos e alimentam nascentes que irrigam as terras secas ao redor, sendo vitais para a agricultura local."}]');

-- ecossistemas — pampa
insert into ecosystems (id, biome, name, category, emoji, image, hero_image, detail_image, description, subtitle, traits, about, importance, fun_facts) values
('campos-nativos', 'pampa', 'Campos nativos', 'Campos nativos', '🌾', null, null, null,
  'Extensas áreas de gramíneas nativas que formam a paisagem típica do Pampa gaúcho.',
  'Pastagens naturais do sul',
  '[{"label":"Tipo","value":"Formação campestre nativa"},{"label":"Vegetação","value":"Gramíneas e leguminosas"},{"label":"Solo","value":"Profundo e fértil"},{"label":"Importância","value":"Pecuária sustentável e biodiversidade"}]',
  'Os campos nativos do Pampa são formações campestres com enorme diversidade de gramíneas, leguminosas e outras herbáceas. Cobrem vastas extensões do sul do Brasil, formando uma paisagem de horizonte aberto. Apesar de parecerem monótonos, abrigam mais de 3.000 espécies de plantas e são a base de uma pecuária extensiva praticada há séculos sobre pastagem natural.',
  '{"title":"Um patrimônio natural subestimado","description":"Os campos nativos do Pampa sustentam a pecuária gaúcha sobre pastagem natural, sem necessidade de desmatamento. São fundamentais para a conservação do solo, a recarga de aquíferos e abrigam espécies ameaçadas como o veado-campeiro e diversas aves endêmicas."}',
  '[{"title":"Biodiversidade invisível","description":"Os campos nativos possuem mais de 3.000 espécies de plantas, mais do que muitas florestas tropicais por área equivalente."},{"title":"Pecuária sobre campo nativo","description":"O gado criado sobre pastagem natural do Pampa dispensa o desmatamento, sendo uma das formas mais sustentáveis de pecuária do mundo."},{"title":"Bioma mais ameaçado","description":"O Pampa já perdeu mais de 50% de sua cobertura original, sendo convertido em lavouras de soja e silvicultura de eucalipto."}]'),

('banhados', 'pampa', 'Banhados', 'Banhados', '💧', null, null, null,
  'Áreas úmidas permanentes que abrigam grande diversidade de aves aquáticas e peixes.',
  'Áreas úmidas permanentes',
  '[{"label":"Tipo","value":"Zona úmida permanente ou sazonal"},{"label":"Vegetação","value":"Macrófitas aquáticas e juncos"},{"label":"Solo","value":"Encharcado e turfoso"},{"label":"Importância","value":"Regulação hídrica e habitat de aves"}]',
  'Os banhados são áreas úmidas permanentes ou sazonais do Pampa, cobertos por vegetação aquática como juncos, aguapés e gravatás. Funcionam como grandes esponjas naturais que regulam o fluxo de água na paisagem. São pontos de concentração de vida silvestre, especialmente aves migratórias que percorrem milhares de quilômetros para se alimentar e reproduzir nessas áreas.',
  '{"title":"Os filtros naturais do Pampa","description":"Os banhados filtram a água que passa por eles, retendo poluentes e sedimentos antes que cheguem aos rios. Regulam cheias ao absorver o excesso de água das chuvas e liberam lentamente na estiagem, mantendo rios e arroios com fluxo constante."}',
  '[{"title":"Rota migratória","description":"Aves como o maçarico viajam do Ártico canadense até os banhados do Pampa todos os anos, percorrendo mais de 15 mil quilômetros."},{"title":"Turfa brasileira","description":"Alguns banhados acumulam camadas de matéria orgânica por milhares de anos, formando turfa — um registro da história climática da região."},{"title":"Banhado do Taim","description":"O Banhado do Taim, no RS, é uma das maiores áreas úmidas do sul do Brasil e refúgio de espécies ameaçadas como o cervo-do-pantanal."}]'),

('matas-ciliares', 'pampa', 'Matas ciliares', 'Matas ciliares', '🌳', null, null, null,
  'Florestas ao longo dos rios que protegem as margens e conectam fragmentos de habitat.',
  'Florestas protetoras dos rios',
  '[{"label":"Tipo","value":"Floresta ribeirinha"},{"label":"Vegetação","value":"Árvores de 10 a 20 metros"},{"label":"Solo","value":"Úmido e aluvial"},{"label":"Importância","value":"Proteção hídrica e corredores ecológicos"}]',
  'As matas ciliares do Pampa são florestas que acompanham rios e arroios, formando faixas de vegetação arbórea em meio aos campos abertos. São compostas por espécies como o salgueiro, a corticeira e o branquilho. Funcionam como corredores que conectam fragmentos florestais isolados e permitem o deslocamento de animais pela paisagem campestre.',
  '{"title":"Os cílios que protegem os rios","description":"Assim como os cílios protegem os olhos, as matas ciliares protegem os rios contra erosão, assoreamento e poluição. Suas raízes seguram o solo das margens e suas copas mantêm a temperatura da água adequada para a vida aquática."}',
  '[{"title":"Origem do nome","description":"O nome \"mata ciliar\" vem da analogia com os cílios dos olhos: assim como os cílios protegem os olhos, essas matas protegem os cursos d''água."},{"title":"Corredores de vida","description":"Animais como o graxaim e o bugio usam as matas ciliares como estradas naturais para se deslocar entre áreas de floresta separadas por campos."},{"title":"Primeiras a desaparecer","description":"As matas ciliares do Pampa são as formações florestais mais ameaçadas do bioma, removidas para dar lugar a lavouras nas margens dos rios."}]');

-- ecossistemas — pantanal
insert into ecosystems (id, biome, name, category, emoji, image, hero_image, detail_image, description, subtitle, traits, about, importance, fun_facts) values
('campos-inundaveis', 'pantanal', 'Campos inundáveis', 'Campos inundáveis', '🌊', null, null, null,
  'Extensas planícies que alagam durante as cheias, formando pastagens naturais para a fauna.',
  'Planície de inundação sazonal',
  '[{"label":"Tipo","value":"Planície de inundação sazonal"},{"label":"Vegetação","value":"Gramíneas aquáticas e terrestres"},{"label":"Ciclo","value":"Cheia (dez–mar) e seca (jul–out)"},{"label":"Importância","value":"Berçário natural de peixes"}]',
  'Os campos inundáveis são o coração do Pantanal. Na cheia, a água cobre tudo e os peixes se reproduzem entre as gramíneas submersas. Na seca, a água recua e os campos viram pastagens ricas, concentrando aves e predadores ao redor das poças remanescentes. Esse ciclo de cheia e seca é o motor de toda a vida no bioma.',
  '{"title":"O pulso das águas","description":"O ciclo de cheia e seca é o motor de toda a vida no Pantanal. Sem ele, o bioma simplesmente não existiria. É a água que cria a abundância de vida que faz do Pantanal um lugar único no planeta."}',
  '[{"title":"Dois mundos","description":"O mesmo campo pode ser um lago de 1 metro de profundidade na cheia e pasto seco na seca."},{"title":"Berçário natural","description":"A maioria dos peixes do Pantanal se reproduz nos campos alagados, entre as gramíneas submersas."},{"title":"Concentração de vida","description":"Na seca, os animais se concentram nas poças remanescentes, criando um dos maiores espetáculos de vida selvagem do mundo."}]'),

('corixos', 'pantanal', 'Corixos', 'Corixos', '🏞️', null, null, null,
  'Canais naturais que conectam rios e lagoas, servindo como corredores de vida aquática.',
  'Canais naturais entre águas',
  '[{"label":"Tipo","value":"Canal natural de drenagem"},{"label":"Vegetação","value":"Mata ciliar e aquáticas flutuantes"},{"label":"Ciclo","value":"Fluxo varia com cheia e seca"},{"label":"Importância","value":"Conexão entre ambientes aquáticos"}]',
  'Os corixos são canais naturais que conectam rios, baías e campos inundáveis no Pantanal. Funcionam como veias que distribuem a água pela planície durante a cheia e drenam o excesso durante a seca. Suas margens são cobertas por vegetação aquática e mata ciliar, criando corredores sombreados por onde peixes, jacarés e lontras se deslocam entre diferentes ambientes.',
  '{"title":"As veias do Pantanal","description":"Os corixos são essenciais para a distribuição de água, nutrientes e organismos por toda a planície pantaneira. Sem eles, a água ficaria represada em poucos pontos e a diversidade de ambientes que caracteriza o Pantanal não existiria."}',
  '[{"title":"Estradas de água","description":"Os ribeirinhos usam os corixos como estradas naturais para navegar entre comunidades e pontos de pesca."},{"title":"Direção variável","description":"Alguns corixos mudam a direção do fluxo de água dependendo da estação, correndo para um lado na cheia e para outro na seca."},{"title":"Tocas de lontra","description":"As margens dos corixos são o habitat favorito das lontras gigantes, que escavam tocas nos barrancos para criar seus filhotes."}]'),

('baias', 'pantanal', 'Baías', 'Baías', '💧', null, null, null,
  'Lagoas circulares formadas pelas cheias, importantes para peixes, jacarés e aves.',
  'Lagoas naturais do Pantanal',
  '[{"label":"Tipo","value":"Lagoa circular permanente ou sazonal"},{"label":"Vegetação","value":"Aguapés, camalotes e vitórias-régias"},{"label":"Solo","value":"Argiloso com acúmulo de matéria orgânica"},{"label":"Importância","value":"Reservatório de água e biodiversidade"}]',
  'As baías são lagoas geralmente circulares ou elípticas espalhadas por toda a planície do Pantanal. Algumas são permanentes e outras secam completamente na estiagem. Suas águas rasas e ricas em nutrientes sustentam densas comunidades de plantas aquáticas, peixes, jacarés e aves. Na seca, as baías que mantêm água se tornam oásis que concentram a fauna de toda a região.',
  '{"title":"Oásis de vida na planície","description":"As baías funcionam como reservatórios naturais que garantem a sobrevivência da fauna durante a estação seca. São pontos de concentração de jacarés, capivaras e aves aquáticas, e sustentam comunidades de plantas aquáticas que produzem oxigênio e filtram a água."}',
  '[{"title":"Formato misterioso","description":"A forma circular das baías intriga cientistas há décadas. Uma teoria sugere que são formadas pela dissolução do calcário subterrâneo."},{"title":"Tapete verde","description":"Na cheia, camalotes e aguapés formam tapetes tão densos sobre as baías que alguns animais caminham sobre eles."},{"title":"Caldeirão de jacarés","description":"Na seca, é possível encontrar centenas de jacarés amontoados em uma única baía, esperando a próxima cheia."}]'),

('capoes', 'pantanal', 'Capões', 'Capões', '🌳', null, null, null,
  'Ilhas de vegetação arbórea em meio aos campos, refúgio para fauna durante as inundações.',
  'Ilhas de floresta nos campos',
  '[{"label":"Tipo","value":"Ilha florestal em campo aberto"},{"label":"Vegetação","value":"Árvores de 8 a 15 metros"},{"label":"Solo","value":"Elevado, não inundável"},{"label":"Importância","value":"Refúgio da fauna na cheia"}]',
  'Os capões são ilhas circulares de vegetação arbórea que se erguem em meio aos campos abertos do Pantanal. Ocupam pequenas elevações do terreno que não são atingidas pelas cheias. Durante as inundações, funcionam como refúgios onde animais terrestres se concentram para escapar da água. Cada capão é um microcosmo com espécies de floresta isoladas na paisagem campestre.',
  '{"title":"As arcas de Noé do Pantanal","description":"Durante as cheias, os capões se tornam verdadeiras arcas de Noé, onde onças, veados, tatus e cobras se refugiam lado a lado nas poucas áreas secas. São essenciais para a sobrevivência da fauna terrestre durante os meses de inundação."}',
  '[{"title":"Convivência forçada","description":"Na cheia, predadores e presas dividem o mesmo capão, criando uma trégua temporária imposta pela água."},{"title":"Criados por cupins","description":"Muitos capões se formam a partir de cupinzeiros que acumulam terra e sementes, criando as elevações onde as árvores crescem."},{"title":"Cada um é único","description":"Cada capão tem composição de espécies diferente dos vizinhos, funcionando como experimentos naturais de colonização vegetal."}]');
